<?php

declare(strict_types=1);

/**
 * Standalone WLS 2.0 host gateway controller.
 *
 * This file intentionally has no framework dependency. GatewayHostManager
 * copies it into an immutable host A/B slot so the gateway can restart after
 * the project that initially installed it has moved away.
 */
final class WlsEdgeProtocolException extends \DomainException
{
    public function __construct(
        private readonly string $protocolCode,
        string $message,
    ) {
        parent::__construct($message);
    }

    public function protocolCode(): string
    {
        return $this->protocolCode;
    }
}

final class WlsNativeBrokerActionException extends \RuntimeException
{
    public function __construct(
        private readonly string $stableCode,
        string $message,
    ) {
        parent::__construct($message);
    }

    public function stableCode(): string
    {
        return $this->stableCode;
    }
}

