    /**
     * Recovery state deliberately retains only durable routing facts. Runtime
     * backend capabilities are fenced by the new gateway epoch and must be
     * submitted again before isolation can be lifted.
     *
     * @param array<string,mixed> $state
     * @return array<string,mixed>
     */
    private function sanitizeIsolationState(array $state): array
    {
        $state['instances'] = [];
        $state['acme_challenges'] = [];
        $state['transfers'] = [];
        foreach ((array)($state['routes'] ?? []) as $routeId => $route) {
            if (!\is_array($route)
                || !$this->routeAllowedBySecurityState($route, $state)
                || (string)($route['status'] ?? '') === 'REMOVED'
            ) {
                unset($state['routes'][$routeId]);
                continue;
            }
            try {
                $projectUuid = \strtolower(\trim((string)($route['project_uuid'] ?? '')));
                $domain = $this->normalizeDomain((string)($route['domain'] ?? ''));
            } catch (\Throwable) {
                unset($state['routes'][$routeId]);
                continue;
            }
            $canonicalRouteId = $this->canonicalRouteId($projectUuid, $domain);
            if (!\hash_equals($canonicalRouteId, (string)$routeId)
                || !\hash_equals($canonicalRouteId, (string)($route['route_id'] ?? ''))
            ) {
                unset($state['routes'][$routeId]);
                continue;
            }
            $certificate = \is_array($route['certificate'] ?? null)
                ? $route['certificate']
                : [];
            if (!$this->certificateSnapshotValidForDomain(
                $certificate,
                $domain,
                $projectUuid,
            )) {
                $certificate['valid'] = false;
                $certificate['snapshot_digest'] = '';
                $certificate['cert_path'] = '';
                $certificate['key_path'] = '';
            }
            $state['routes'][$routeId] = [
                'route_id' => (string)($route['route_id'] ?? $routeId),
                'project_uuid' => $projectUuid,
                'project_root' => (string)($route['project_root'] ?? ''),
                'enrollment_security_generation' => (int)(
                    $route['enrollment_security_generation'] ?? 0
                ),
                'instance_id' => '',
                'domain' => $domain,
                'backends' => [],
                'backend_instances' => [],
                'backend_identity' => [],
                'instances' => [],
                'certificate' => $certificate,
                'route_generation' => \max(1, (int)($route['route_generation'] ?? 0)),
                'domain_security_generation' => (int)(
                    $route['domain_security_generation'] ?? 0
                ),
                'status' => 'STALE',
                'last_heartbeat' => 0,
                'last_backend_probe' => 0,
                'stale_since' => \time(),
                'stale_since_monotonic' => $this->monotonicNow(),
                'stale_boot_id' => $this->hostBootId,
                'drain_until' => null,
                'force_https' => (bool)($route['force_https'] ?? true),
                'force_root_to_www' => (bool)(
                    $route['force_root_to_www'] ?? false
                ),
                'recovery_required' => true,
                'updated_at' => \gmdate(DATE_ATOM),
            ];
        }
        $state['isolation_mode'] = true;
        $state['ready'] = false;
        $state['active_routes'] = [];
        $state['active_config_digest'] = '';
        $state['pending_lkg_generation'] = 0;
        $state['pending_lkg_since'] = 0;
        $state['pending_lkg_since_monotonic'] = 0.0;
        $state['pending_lkg_boot_id'] = '';
        $state['pending_lkg_config_digest'] = '';
        $state['pending_lkg_routes_digest'] = '';
        return $state;
    }

    /** @return array<string,array<string,mixed>> */
    private function recoverableLkgRoutes(): array
    {
        $routes = $this->loadRouteLkg();
        if ($routes !== []) {
            return $routes;
        }
        foreach ($this->discoverLkgEntries() as $entry) {
            $bundle = $this->loadLkgBundle($entry);
            if ($bundle !== null) {
                return (array)$bundle['routes'];
            }
        }
        return [];
    }

    /** @return list<array<string,mixed>> */
    private function discoverLkgEntries(): array
    {
        $entries = [];
        try {
            $leaves = $this->boundedDirectoryEntries(
                $this->lkgDir(),
                self::MAX_HOST_DIRECTORY_ENTRIES,
                'Gateway LKG root',
            );
        } catch (\Throwable) {
            return [];
        }
        foreach ($leaves as $leaf) {
            if (\preg_match(
                '/\Ageneration-([1-9][0-9]*)-([a-f0-9]{16})\z/D',
                (string)$leaf,
                $matches,
            ) !== 1) {
                continue;
            }
            $bundle = $this->lkgDir() . DIRECTORY_SEPARATOR . $leaf;
            $entry = [
                'generation' => (int)$matches[1],
                'bundle_dir' => $bundle,
                'manifest_file' => $bundle . DIRECTORY_SEPARATOR . 'manifest.json',
                'file' => $bundle . DIRECTORY_SEPARATOR . 'nginx.conf',
                'route_file' => $bundle . DIRECTORY_SEPARATOR . 'routes.json',
            ];
            if ($this->loadLkgBundle($entry) !== null) {
                $entries[] = $entry;
            }
        }
        \usort(
            $entries,
            static fn (array $left, array $right): int =>
                (int)$right['generation'] <=> (int)$left['generation'],
        );
        return \array_slice($entries, 0, 2);
    }

    /** @param array<string,array<string,array<string,mixed>>> $retirements */
    private function validInstanceRetirements(array $retirements): bool
    {
        if (\count($retirements) > self::MAX_PROJECTS) {
            return false;
        }
        $total = 0;
        foreach ($retirements as $projectUuid => $instances) {
            if (!\is_string($projectUuid)
                || !$this->validProjectUuid($projectUuid)
                || !\is_array($instances)
                || \count($instances) > self::MAX_RETIRED_INSTANCES_PER_PROJECT
            ) {
                return false;
            }
            $total += \count($instances);
            if ($total > self::MAX_TOTAL_RETIRED_INSTANCES) {
                return false;
            }
            foreach ($instances as $instanceId => $retirement) {
                if (!\is_string($instanceId)
                    || \preg_match(
                        '/\A[a-zA-Z0-9][a-zA-Z0-9._-]{0,127}\z/D',
                        $instanceId,
                    ) !== 1
                    || !\is_array($retirement)
                    || !$this->validInstanceRetirementEntry(
                        $retirement,
                        $projectUuid,
                        $instanceId,
                    )
                ) {
                    return false;
                }
            }
        }
        return true;
    }

    /** @param array<string,array<string,mixed>> $floors */
    private function validCertificateFloors(array $floors): bool
    {
        foreach ($floors as $key => $floor) {
            if (!\is_string($key) || !\is_array($floor)) {
                return false;
            }
            $projectUuid = (string)($floor['project_uuid'] ?? '');
            $domain = (string)($floor['domain'] ?? '');
            try {
                $normalizedDomain = $this->normalizeDomain($domain);
            } catch (\Throwable) {
                return false;
            }
            $generation = (int)($floor['generation'] ?? 0);
            $sourceDigest = \strtolower(\trim((string)(
                $floor['source_digest'] ?? ''
            )));
            $trustProfile = \strtolower(\trim((string)(
                $floor['trust_profile'] ?? ''
            )));
            $provider = \strtolower(\trim((string)($floor['provider'] ?? '')));
            $materialClass = \strtolower(\trim((string)(
                $floor['material_class'] ?? ''
            )));
            $provenanceDigest = \strtolower(\trim((string)(
                $floor['provenance_digest'] ?? ''
            )));
            $revocationGeneration = (int)($floor['revocation_generation'] ?? 0);
            $revocationDigest = \strtolower(\trim((string)(
                $floor['revocation_source_digest'] ?? ''
            )));
            $revocationTrustProfile = \strtolower(\trim((string)(
                $floor['revocation_trust_profile'] ?? ''
            )));
            $revocationProvenanceDigest = \strtolower(\trim((string)(
                $floor['revocation_provenance_digest'] ?? ''
            )));
            $profileValid = \in_array($trustProfile, [
                self::CERTIFICATE_TRUST_PROFILE_PRODUCTION,
                self::CERTIFICATE_TRUST_PROFILE_TEST,
            ], true);
            $activeProvenanceValid = $profileValid
                && \in_array($provider, self::CERTIFICATE_PROVIDERS, true)
                && \in_array(
                    $materialClass,
                    self::CERTIFICATE_MATERIAL_CLASSES,
                    true,
                )
                && ($trustProfile !== self::CERTIFICATE_TRUST_PROFILE_PRODUCTION
                    || $materialClass === 'public_trusted')
                && \hash_equals(
                    $this->certificateProvenanceDigest(
                        $domain,
                        $sourceDigest,
                        $trustProfile,
                        $provider,
                        $materialClass,
                    ),
                    $provenanceDigest,
                );
            $disabledProvenanceValid = $profileValid
                && $provider === 'none'
                && $materialClass === 'none'
                && \hash_equals(
                    \hash(
                        'sha256',
                        "wls-disabled-certificate\0" . $domain . "\0" . $generation,
                    ),
                    $sourceDigest,
                )
                && \hash_equals(
                    $this->inactiveCertificateProvenanceDigest(
                        $domain,
                        'disabled',
                        $sourceDigest,
                        $generation,
                        $trustProfile,
                    ),
                    $provenanceDigest,
                );
            if ((int)($floor['schema_version'] ?? 0) !== 2
                || !$this->validProjectUuid($projectUuid)
                || !\hash_equals($normalizedDomain, $domain)
                || !\hash_equals($this->certificateFloorKey($projectUuid, $domain), $key)
                || $generation < 1
                || \preg_match('/\A[a-f0-9]{64}\z/D', $sourceDigest) !== 1
                || \preg_match('/\A[a-f0-9]{64}\z/D', $provenanceDigest) !== 1
                || (!$activeProvenanceValid && !$disabledProvenanceValid)
                || (int)($floor['route_generation'] ?? 0) < 1
                || $revocationGeneration < 0
                || $revocationGeneration > $generation
                || ($revocationGeneration === 0
                    && ($revocationDigest !== ''
                        || $revocationTrustProfile !== ''
                        || $revocationProvenanceDigest !== ''))
                || ($revocationGeneration > 0
                    && (!\in_array($revocationTrustProfile, [
                            self::CERTIFICATE_TRUST_PROFILE_PRODUCTION,
                            self::CERTIFICATE_TRUST_PROFILE_TEST,
                        ], true)
                        || \preg_match('/\A[a-f0-9]{64}\z/D', $revocationDigest) !== 1
                        || \preg_match(
                            '/\A[a-f0-9]{64}\z/D',
                            $revocationProvenanceDigest,
                        ) !== 1
                        || !\hash_equals(
                            \hash(
                                'sha256',
                                "wls-disabled-certificate\0" . $domain . "\0"
                                    . $revocationGeneration,
                            ),
                            $revocationDigest,
                        )
                        || !\hash_equals(
                            $this->inactiveCertificateProvenanceDigest(
                                $domain,
                                'disabled',
                                $revocationDigest,
                                $revocationGeneration,
                                $revocationTrustProfile,
                            ),
                            $revocationProvenanceDigest,
                        )))
            ) {
                return false;
            }
        }
        return true;
    }

    /** @param array<string,mixed> $retirement */
    private function validInstanceRetirementEntry(
        array $retirement,
        string $projectUuid,
        string $instanceId,
    ): bool {
        $retiredAt = (string)($retirement['retired_at'] ?? '');
        $retiredAtValue = $retiredAt !== ''
            ? \DateTimeImmutable::createFromFormat(DATE_ATOM, $retiredAt)
            : false;
        $digest = (string)($retirement['retirement_digest'] ?? '');
        return (int)($retirement['schema_version'] ?? 0) === 1
            && \hash_equals($projectUuid, (string)($retirement['project_uuid'] ?? ''))
            && \hash_equals($instanceId, (string)($retirement['instance_id'] ?? ''))
            && (int)($retirement['instance_generation'] ?? 0) >= 1
            && (int)($retirement['master_epoch'] ?? 0) >= 1
            && \preg_match(
                '/\A[a-f0-9]{32}\z/D',
                (string)($retirement['launch_id'] ?? ''),
            ) === 1
            && \preg_match(
                '/\A[a-f0-9]{64}\z/D',
                (string)($retirement['instance_digest'] ?? ''),
            ) === 1
            && \preg_match(
                '/\A[a-f0-9]{32}\z/D',
                (string)($retirement['gateway_epoch'] ?? ''),
            ) === 1
            && \preg_match(
                '/\A[a-f0-9]{64}\z/D',
                (string)($retirement['host_boot_id'] ?? ''),
            ) === 1
            && \preg_match(
                '/\A[a-f0-9]{32}\z/D',
                (string)($retirement['transaction_id'] ?? ''),
            ) === 1
            && \is_int($retirement['retired_unix'] ?? null)
            && (int)$retirement['retired_unix'] >= 1
            && $retiredAtValue instanceof \DateTimeImmutable
            && $retiredAtValue->format(DATE_ATOM) === $retiredAt
            && \preg_match('/\A[a-f0-9]{64}\z/D', $digest) === 1
            && \hash_equals($digest, $this->instanceRetirementDigest($retirement));
    }

    /** @param array<string,mixed> $retirement */
    private function instanceRetirementDigest(array $retirement): string
    {
        unset($retirement['retirement_digest']);
        return \hash('sha256', $this->canonicalJson($retirement));
    }

    /**
     * @return array<string,mixed>
     */
    private function instanceRetirementFloor(
        string $projectUuid,
        string $instanceId,
    ): array {
        $floor = $this->state['instance_retirements'][$projectUuid][$instanceId] ?? null;
        $floor = \is_array($floor) ? $floor : [];
        foreach ((array)($this->publication['instance_retirement_candidates'] ?? [])
            as $candidate
        ) {
            if (!\is_array($candidate)
                || !\hash_equals(
                    $projectUuid,
                    (string)($candidate['project_uuid'] ?? ''),
                )
                || !\hash_equals(
                    $instanceId,
                    (string)($candidate['instance_id'] ?? ''),
                )
            ) {
                continue;
            }
            if (!$this->validInstanceRetirementEntry(
                $candidate,
                $projectUuid,
                $instanceId,
            )) {
                throw new \RuntimeException(
                    'Pending instance retirement candidate is malformed.'
                );
            }
            if ((int)($candidate['instance_generation'] ?? 0)
                > (int)($floor['instance_generation'] ?? 0)
            ) {
                $floor = $candidate;
            }
        }
        return $floor;
    }

    /** @return array<string,mixed> */
    private function assertInstanceRetirementFence(
        string $projectUuid,
        string $instanceId,
        int $instanceGeneration,
    ): array {
        $floor = $this->instanceRetirementFloor($projectUuid, $instanceId);
        if ($floor !== []
            && $instanceGeneration <= (int)($floor['instance_generation'] ?? 0)
        ) {
            throw new WlsEdgeProtocolException(
                'instance_generation_retired',
                'Instance generation was permanently retired; increment instance_generation '
                    . 'and submit a full registration.',
            );
        }
        return $floor;
    }

    /** @param array<string,mixed> $instance @return array<string,mixed> */
    private function stageInstanceRetirementCandidate(
        string $projectUuid,
        string $instanceId,
        array $instance,
    ): array {
        if ($this->publication === null) {
            throw new \RuntimeException(
                'Instance retirement requires an active publication transaction.'
            );
        }
        $transactionId = (string)($this->publication['transaction_id'] ?? '');
        $retirement = [
            'schema_version' => 1,
            'project_uuid' => $projectUuid,
            'instance_id' => $instanceId,
            'instance_generation' => (int)($instance['generation'] ?? 0),
            'instance_digest' => (string)($instance['digest'] ?? ''),
            'master_epoch' => (int)($instance['master_epoch'] ?? 0),
            'launch_id' => (string)($instance['launch_id'] ?? ''),
            'gateway_epoch' => (string)($this->state['epoch'] ?? ''),
            'host_boot_id' => $this->hostBootId,
            'transaction_id' => $transactionId,
            'retired_unix' => \time(),
            'retired_at' => \gmdate(DATE_ATOM),
        ];
        $retirement['retirement_digest'] = $this->instanceRetirementDigest($retirement);
        if (!$this->validInstanceRetirementEntry(
            $retirement,
            $projectUuid,
            $instanceId,
        )) {
            throw new \RuntimeException('Instance retirement candidate is malformed.');
        }

        $known = [];
        foreach ((array)($this->state['instance_retirements'] ?? [])
            as $knownProject => $knownInstances
        ) {
            foreach ((array)$knownInstances as $knownInstance => $_retirement) {
                $known[(string)$knownProject . "\0" . (string)$knownInstance] = true;
            }
        }
        foreach ((array)($this->publication['instance_retirement_candidates'] ?? [])
            as $candidate
        ) {
            if (\is_array($candidate)) {
                $known[(string)($candidate['project_uuid'] ?? '') . "\0"
                    . (string)($candidate['instance_id'] ?? '')] = true;
            }
        }
        $candidateKey = $projectUuid . "\0" . $instanceId;
        if (!isset($known[$candidateKey])) {
            $projectCount = 0;
            foreach (\array_keys($known) as $knownKey) {
                if (\str_starts_with($knownKey, $projectUuid . "\0")) {
                    ++$projectCount;
                }
            }
            if ($projectCount >= self::MAX_RETIRED_INSTANCES_PER_PROJECT
                || \count($known) >= self::MAX_TOTAL_RETIRED_INSTANCES
            ) {
                throw new WlsEdgeProtocolException(
                    'instance_retirement_quota_exceeded',
                    'The host instance-retirement ledger is full; administrator repair is required.',
                );
            }
        }
        $key = \hash('sha256', $candidateKey);
        $existing = $this->publication['instance_retirement_candidates'][$key] ?? null;
        if (\is_array($existing)
            && (int)($existing['instance_generation'] ?? 0)
                > (int)$retirement['instance_generation']
        ) {
            throw new \RuntimeException(
                'Instance retirement candidate attempted to move its floor backward.'
            );
        }
        $this->publication['instance_retirement_candidates'][$key] = $retirement;
        $this->persistPublication();
        return $retirement;
    }

    private function commitInstanceRetirementCandidates(): void
    {
        if ($this->publication === null) {
            return;
        }
        $candidates = (array)(
            $this->publication['instance_retirement_candidates'] ?? []
        );
        if ($candidates === []) {
            return;
        }
        \ksort($candidates, SORT_STRING);
        $advanced = [];
        foreach ($candidates as $candidate) {
            if (!\is_array($candidate)) {
                throw new \RuntimeException(
                    'Committed instance retirement candidate is malformed.'
                );
            }
            $projectUuid = (string)($candidate['project_uuid'] ?? '');
            $instanceId = (string)($candidate['instance_id'] ?? '');
            if (!$this->validInstanceRetirementEntry(
                $candidate,
                $projectUuid,
                $instanceId,
            )) {
                throw new \RuntimeException(
                    'Committed instance retirement candidate failed its digest fence.'
                );
            }
            $active = $this->state['instances'][$projectUuid][$instanceId] ?? null;
            if (\is_array($active)
                && (int)($active['generation'] ?? 0)
                    <= (int)$candidate['instance_generation']
            ) {
                throw new \RuntimeException(
                    'Committed retirement would leave a retired instance generation active.'
                );
            }
            $existing = $this->state['instance_retirements'][$projectUuid][$instanceId]
                ?? null;
            $existingGeneration = \is_array($existing)
                ? (int)($existing['instance_generation'] ?? 0)
                : 0;
            if ($existingGeneration === (int)$candidate['instance_generation']
                && \is_array($existing)
                && !\hash_equals(
                    (string)($existing['retirement_digest'] ?? ''),
                    (string)$candidate['retirement_digest'],
                )
            ) {
                throw new \RuntimeException(
                    'Equal instance retirement generations have different security digests.'
                );
            }
            if ((int)$candidate['instance_generation'] > $existingGeneration) {
                $this->state['instance_retirements'][$projectUuid][$instanceId]
                    = $candidate;
                $advanced[] = $candidate;
            }
        }
        if ($advanced === []) {
            return;
        }
        $this->markPublicationIrrevocableSecurity();
        $this->retainSecurityClosureAcrossRoutingRollback();
        $this->persistSecurityLedger();
        $this->persistState();
        foreach ($advanced as $retirement) {
            if (!$this->journal('instance_retired', [
                'project_uuid' => (string)$retirement['project_uuid'],
                'instance_id' => (string)$retirement['instance_id'],
                'instance_generation' => (int)$retirement['instance_generation'],
                'master_epoch' => (int)$retirement['master_epoch'],
                'launch_id' => (string)$retirement['launch_id'],
                'transaction_id' => (string)$retirement['transaction_id'],
                'retirement_digest' => (string)$retirement['retirement_digest'],
            ])) {
                // The monotonic floor and matching route removal are already
                // durable at this point. Throwing would enter the request-level
                // rollback path and could restore an instance at or below that
                // irreversible floor. Journal failure has already fenced later
                // mutations and published the disk-pressure marker; preserve
                // the safe state and let recovery repair the audit chain.
                $this->state['recovery']['pending_security_audit'] = [
                    'kind' => 'INSTANCE_RETIREMENT',
                    'reason' => 'instance_retirement_audit_append_failed',
                    'project_uuid' => (string)$retirement['project_uuid'],
                    'instance_id' => (string)$retirement['instance_id'],
                    'instance_generation' => (int)$retirement['instance_generation'],
                ];
                $this->maintenanceDiskPressureLatched();
                break;
            }
        }
    }

    /**
     * @param array<string,array<string,mixed>> $enrollments
     * @param array<string,array<string,mixed>> $tombstones
     */
    private function securityGenerationHighWater(array $enrollments, array $tombstones): int
    {
        $highWater = 0;
        foreach ($enrollments as $enrollment) {
            if (\is_array($enrollment)) {
                $highWater = \max(
                    $highWater,
                    (int)($enrollment['security_generation'] ?? 0),
                );
            }
        }
        foreach ($tombstones as $tombstone) {
            if (\is_array($tombstone)) {
                $highWater = \max($highWater, (int)($tombstone['generation'] ?? 0));
            }
        }
        return $highWater;
    }

    /**
     * Validate both sides of every durable enrollment relation. Stored
     * digests are evidence only after all transaction/enrollment facts are
     * recomputed and compared; otherwise a self-consistent envelope could
     * authorize a credential for facts different from its digest.
     *
     * @param array<string,mixed> $transactions
     * @param array<string,mixed> $enrollments
     */
    private function validEnrollmentLedgerClosure(
        array $transactions,
        array $enrollments,
        array $tombstones,
        array $rotationTransactions,
        array $securityTransactions,
    ): bool {
        if ($this->activeEnrollmentTransactionCount($transactions)
                > self::MAX_ENROLLMENT_TRANSACTIONS
            || !$this->validEnrollmentControllerGenerations($transactions)
        ) {
            return false;
        }
        try {
            foreach ($transactions as $transactionId => $transaction) {
                if (!\is_array($transaction)
                    || !$this->validEnrollmentTransactionClosure(
                        (string)$transactionId,
                        $transaction,
                        $enrollments,
                        $tombstones,
                        $rotationTransactions,
                        $securityTransactions,
                        $transactions,
                    )
                ) {
                    return false;
                }
            }
        } catch (\Throwable) {
            return false;
        }
        return true;
    }

    /**
     * @param array<string,mixed> $transaction
     * @param array<string,mixed> $enrollments
     */
    private function validEnrollmentTransactionClosure(
        string $transactionId,
        array $transaction,
        array $enrollments,
        array $tombstones,
        array $rotationTransactions,
        array $securityTransactions,
        array $enrollmentTransactions,
    ): bool {
        $schema = (int)($transaction['schema_version'] ?? 1);
        $phase = (string)($transaction['phase'] ?? '');
        $projectUuid = (string)($transaction['project_uuid'] ?? '');
        $projectRoot = (string)($transaction['project_root'] ?? '');
        $roots = $transaction['certificate_roots'] ?? null;
        $domains = $transaction['allowed_domains'] ?? null;
        $owner = $transaction['owner'] ?? null;
        $capabilities = $transaction['capabilities'] ?? null;
        if (!\in_array($schema, [1, 2, 3], true)
            || \preg_match('/\A[a-f0-9]{32}\z/D', $transactionId) !== 1
            || !\hash_equals(
                $transactionId,
                (string)($transaction['transaction_id'] ?? ''),
            )
            || !$this->validProjectUuid($projectUuid)
            || $projectRoot === ''
            || !\is_array($roots)
            || !\is_array($domains)
            || !\is_array($owner)
            || !\is_array($capabilities)
            || !\in_array($phase, [
                'PREPARED',
                'ABORT_PENDING',
                'ABORTED',
                'LEDGER_COMMITTED',
                'BROKER_COMMITTED',
                'COMMITTED',
                'SUPERSEDED',
            ], true)
            || \preg_match(
                '/\A[a-f0-9]{64}\z/D',
                (string)($transaction['request_digest'] ?? ''),
            ) !== 1
            || \preg_match(
                '/\A[a-f0-9]{64}\z/D',
                (string)($transaction['authenticated_desired_digest'] ?? ''),
            ) !== 1
            || \preg_match(
                '/\A[a-f0-9]{64}\z/D',
                (string)($transaction['authenticated_peer_digest'] ?? ''),
            ) !== 1
            || \preg_match(
                '/\A[a-f0-9]{64}\z/D',
                (string)($transaction['domains_digest'] ?? ''),
            ) !== 1
        ) {
            return false;
        }
        if (($schema >= 3
                && !$this->validEnrollmentPriorAuthority(
                    $transactionId,
                    $transaction,
                    $enrollmentTransactions,
                    $rotationTransactions,
                ))
            || ($schema < 3
                && \array_key_exists('prior_authority', $transaction))
        ) {
            return false;
        }
        $sortedRoots = $roots;
        \ksort($sortedRoots, SORT_STRING);
        $normalizedDomains = [];
        foreach ($domains as $domain) {
            if (!\is_string($domain)) {
                return false;
            }
            $normalizedDomains[] = $this->normalizeDomain($domain);
        }
        $normalizedDomains = \array_values(\array_unique($normalizedDomains));
        \sort($normalizedDomains, SORT_STRING);
        $normalizedCapabilities = $this->normalizeEnrollmentCapabilities(
            $capabilities,
        );
        \ksort($normalizedCapabilities, SORT_STRING);
        if (!\hash_equals(
                $this->canonicalJson($roots),
                $this->canonicalJson($sortedRoots),
            )
            || !\hash_equals(
                $this->canonicalJson($domains),
                $this->canonicalJson($normalizedDomains),
            )
            || !\hash_equals(
                $this->canonicalJson($capabilities),
                $this->canonicalJson($normalizedCapabilities),
            )
            || !\hash_equals(
                (string)$transaction['domains_digest'],
                \hash('sha256', $this->canonicalJson($domains)),
            )
            || !\hash_equals(
                (string)$transaction['authenticated_peer_digest'],
                \hash('sha256', $this->canonicalJson($owner)),
            )
            || !\hash_equals(
                (string)$transaction['authenticated_desired_digest'],
                \hash('sha256', $this->canonicalJson([
                    'project_uuid' => $projectUuid,
                    'project_root' => $projectRoot,
                    'certificate_roots' => $roots,
                    'allowed_domains' => $domains,
                    'owner' => $owner,
                    'capabilities' => $capabilities,
                ])),
            )
        ) {
            return false;
        }
        $terminalWithEnrollment = \in_array(
            $phase,
            ['LEDGER_COMMITTED', 'BROKER_COMMITTED', 'COMMITTED'],
            true,
        );
        if (!$terminalWithEnrollment) {
            return \hash_equals('SUPERSEDED', $phase)
                ? $this->validSupersededEnrollmentTransaction(
                    $transactionId,
                    $transaction,
                    $enrollmentTransactions,
                )
                : true;
        }
        $enrollment = $enrollments[$projectUuid] ?? null;
        if (!\is_array($enrollment)) {
            $enrollment = $this->retiredEnrollmentClosureSnapshot(
                $transaction,
                $tombstones,
                $rotationTransactions,
                $securityTransactions,
            );
        }
        if (!\is_array($enrollment)
            || \preg_match(
                '/\A[a-f0-9]{32}\z/D',
                (string)($transaction['credential_id'] ?? ''),
            ) !== 1
            || \preg_match(
                '/\A[a-f0-9]{64}\z/D',
                (string)($transaction['credential_secret'] ?? ''),
            ) !== 1
            || (int)($transaction['credential_generation'] ?? 0) < 1
            || (int)($transaction['security_generation'] ?? 0) < 1
        ) {
            return false;
        }
        $enrollmentDesired = [
            'project_uuid' => (string)($enrollment['project_uuid'] ?? ''),
            'project_root' => (string)($enrollment['project_root'] ?? ''),
            'certificate_roots' => (array)($enrollment['certificate_roots'] ?? []),
            'allowed_domains' => (array)($enrollment['allowed_domains'] ?? []),
            'owner' => (array)($enrollment['owner'] ?? []),
            'capabilities' => (array)($enrollment['capabilities'] ?? []),
        ];
        return \hash_equals($projectUuid, $enrollmentDesired['project_uuid'])
            && \hash_equals($projectRoot, $enrollmentDesired['project_root'])
            && \hash_equals(
                $this->canonicalJson($roots),
                $this->canonicalJson($enrollmentDesired['certificate_roots']),
            )
            && \hash_equals(
                $this->canonicalJson($domains),
                $this->canonicalJson($enrollmentDesired['allowed_domains']),
            )
            && \hash_equals(
                $this->canonicalJson($owner),
                $this->canonicalJson($enrollmentDesired['owner']),
            )
            && \hash_equals(
                $this->canonicalJson($capabilities),
                $this->canonicalJson($enrollmentDesired['capabilities']),
            )
            && \hash_equals(
                (string)$transaction['authenticated_desired_digest'],
                (string)($enrollment['desired_digest'] ?? ''),
            )
            && \hash_equals(
                (string)($enrollment['desired_digest'] ?? ''),
                \hash('sha256', $this->canonicalJson($enrollmentDesired)),
            )
            && \hash_equals(
                $transactionId,
                (string)($enrollment['enrollment_transaction_id'] ?? ''),
            )
            && \hash_equals(
                $transactionId,
                (string)($enrollment['native_authorization_transaction_id'] ?? ''),
            )
            && \hash_equals(
                (string)$transaction['authenticated_desired_digest'],
                (string)($enrollment['native_authorization_intent_digest'] ?? ''),
            )
            && \hash_equals(
                (string)$transaction['request_digest'],
                (string)($enrollment['client_request_digest'] ?? ''),
            )
            && \hash_equals(
                (string)$transaction['authenticated_peer_digest'],
                (string)($enrollment['authenticated_peer_digest'] ?? ''),
            )
            && \hash_equals(
                (string)$transaction['credential_id'],
                (string)($enrollment['credential_id'] ?? ''),
            )
            && \hash_equals(
                (string)$transaction['credential_secret'],
                (string)($enrollment['credential_secret'] ?? ''),
            )
            && (int)$transaction['credential_generation']
                === (int)($enrollment['credential_generation'] ?? 0)
            && (int)$transaction['security_generation']
                === (int)($enrollment['security_generation'] ?? 0);
    }

    /**
     * @param array<string,mixed> $transaction
     * @param array<string,mixed> $enrollmentTransactions
     * @param array<string,mixed> $rotationTransactions
     */
    private function validEnrollmentPriorAuthority(
        string $transactionId,
        array $transaction,
        array $enrollmentTransactions,
        array $rotationTransactions,
    ): bool {
        $prior = $transaction['prior_authority'] ?? null;
        $credentialGeneration = (int)(
            $transaction['credential_generation'] ?? 0
        );
        if (!\is_array($prior)) {
            return false;
        }
        if ($prior === []) {
            return $credentialGeneration === 1;
        }
        if (\array_keys($prior) !== [
                'schema_version',
                'family',
                'transaction_id',
                'project_uuid',
                'security_generation',
                'credential_generation',
                'credential_id',
                'desired_digest',
                'enrollment_projection',
                'enrollment_projection_digest',
            ]
            || (int)($prior['schema_version'] ?? 0) !== 1
            || !\in_array(
                (string)($prior['family'] ?? ''),
                ['enrollment', 'rotation'],
                true,
            )
            || \preg_match(
                '/\A[a-f0-9]{32}\z/D',
                (string)($prior['transaction_id'] ?? ''),
            ) !== 1
            || \hash_equals(
                $transactionId,
                (string)$prior['transaction_id'],
            )
            || !\hash_equals(
                (string)($transaction['project_uuid'] ?? ''),
                (string)($prior['project_uuid'] ?? ''),
            )
            || !\is_int($prior['security_generation'] ?? null)
            || (int)$prior['security_generation'] < 1
            || !\is_int($prior['credential_generation'] ?? null)
            || (int)$prior['credential_generation'] < 1
            || $credentialGeneration
                !== (int)$prior['credential_generation'] + 1
            || !\hash_equals(
                (string)($transaction['project_root'] ?? ''),
                (string)(
                    $prior['enrollment_projection']['project_root'] ?? ''
                ),
            )
            || \preg_match(
                '/\A[a-f0-9]{32}\z/D',
                (string)($prior['credential_id'] ?? ''),
            ) !== 1
            || \hash_equals(
                (string)($transaction['credential_id'] ?? ''),
                (string)$prior['credential_id'],
            )
            || \preg_match(
                '/\A[a-f0-9]{64}\z/D',
                (string)($prior['desired_digest'] ?? ''),
            ) !== 1
            || !\is_array($prior['enrollment_projection'] ?? null)
            || !$this->validEnrollmentSecurityProjection(
                (array)$prior['enrollment_projection'],
                (string)$prior['project_uuid'],
            )
            || !\hash_equals(
                (string)$prior['enrollment_projection_digest'],
                \hash(
                    'sha256',
                    $this->canonicalJson((array)$prior[
                        'enrollment_projection'
                    ]),
                ),
            )
            || !\hash_equals(
                (string)$prior['credential_id'],
                (string)$prior['enrollment_projection']['credential_id'],
            )
            || !\hash_equals(
                (string)$prior['desired_digest'],
                (string)$prior['enrollment_projection']['desired_digest'],
            )
            || (int)$prior['security_generation']
                !== (int)$prior['enrollment_projection']['security_generation']
            || (int)$prior['credential_generation']
                !== (int)$prior['enrollment_projection'][
                    'credential_generation'
                ]
        ) {
            return false;
        }
        $securityGeneration = (int)(
            $transaction['security_generation'] ?? 0
        );
        if ($securityGeneration > 0
            && $securityGeneration <= (int)$prior['security_generation']
        ) {
            return false;
        }
        $priorTransactionId = (string)$prior['transaction_id'];
        if (\hash_equals('enrollment', (string)$prior['family'])) {
            $previous = $enrollmentTransactions[$priorTransactionId] ?? null;
            return \is_array($previous)
                && \in_array(
                    (string)($previous['phase'] ?? ''),
                    ['COMMITTED', 'SUPERSEDED'],
                    true,
                )
                && (int)($previous['security_generation'] ?? 0)
                    === (int)$prior['security_generation']
                && $this->enrollmentProjectionMatchesTransactionAuthority(
                    (array)$prior['enrollment_projection'],
                    $previous,
                    $priorTransactionId,
                );
        }
        $rotation = $rotationTransactions[$priorTransactionId] ?? null;
        $finalProjection = \is_array($rotation)
            ? ($rotation['final_enrollment_snapshot'] ?? null)
            : null;
        return \is_array($rotation)
            && \hash_equals(
                'FINALIZED',
                (string)($rotation['phase'] ?? ''),
            )
            && \hash_equals(
                (string)$prior['project_uuid'],
                (string)($rotation['new_project_uuid'] ?? ''),
            )
            && (int)($rotation['security_generation'] ?? 0)
                === (int)$prior['security_generation']
            && \is_array($finalProjection)
            && \hash_equals(
                (string)(
                    $rotation['final_enrollment_snapshot_digest'] ?? ''
                ),
                \hash('sha256', $this->canonicalJson($finalProjection)),
            )
            && \hash_equals(
                $this->canonicalJson((array)$prior['enrollment_projection']),
                $this->canonicalJson($finalProjection),
            );
    }

    /**
     * @param array<string,mixed> $transaction
     * @param array<string,mixed> $enrollmentTransactions
     */
    private function validSupersededEnrollmentTransaction(
        string $transactionId,
        array $transaction,
        array $enrollmentTransactions,
    ): bool {
        $receipt = $transaction['superseded_by_enrollment'] ?? null;
        if (!\is_array($receipt)
            || \array_keys($receipt) !== [
                'schema_version',
                'transaction_id',
                'project_uuid',
                'security_generation',
                'credential_generation',
                'desired_digest',
                'prior_authority_digest',
            ]
            || (int)($receipt['schema_version'] ?? 0) !== 1
            || \preg_match(
                '/\A[a-f0-9]{32}\z/D',
                (string)($receipt['transaction_id'] ?? ''),
            ) !== 1
            || !\hash_equals(
                (string)($transaction['project_uuid'] ?? ''),
                (string)($receipt['project_uuid'] ?? ''),
            )
            || !\is_int($receipt['security_generation'] ?? null)
            || (int)$receipt['security_generation']
                <= (int)($transaction['security_generation'] ?? 0)
            || !\is_int($receipt['credential_generation'] ?? null)
            || (int)$receipt['credential_generation']
                !== (int)($transaction['credential_generation'] ?? 0) + 1
            || \preg_match(
                '/\A[a-f0-9]{64}\z/D',
                (string)($receipt['desired_digest'] ?? ''),
            ) !== 1
            || \preg_match(
                '/\A[a-f0-9]{64}\z/D',
                (string)($receipt['prior_authority_digest'] ?? ''),
            ) !== 1
            || !\is_string($transaction['superseded_at'] ?? null)
            || (string)$transaction['superseded_at'] === ''
        ) {
            return false;
        }
        $successorId = (string)$receipt['transaction_id'];
        $successor = $enrollmentTransactions[$successorId] ?? null;
        $prior = \is_array($successor)
            ? ($successor['prior_authority'] ?? null)
            : null;
        return \is_array($successor)
            && \in_array(
                (string)($successor['phase'] ?? ''),
                [
                    'LEDGER_COMMITTED',
                    'BROKER_COMMITTED',
                    'COMMITTED',
                    'SUPERSEDED',
                ],
                true,
            )
            && \is_array($prior)
            && \hash_equals(
                'enrollment',
                (string)($prior['family'] ?? ''),
            )
            && \hash_equals(
                $transactionId,
                (string)($prior['transaction_id'] ?? ''),
            )
            && \hash_equals(
                (string)$receipt['project_uuid'],
                (string)($successor['project_uuid'] ?? ''),
            )
            && (int)$receipt['security_generation']
                === (int)($successor['security_generation'] ?? 0)
            && (int)$receipt['credential_generation']
                === (int)($successor['credential_generation'] ?? 0)
            && \hash_equals(
                (string)$receipt['desired_digest'],
                (string)(
                    $successor['authenticated_desired_digest'] ?? ''
                ),
            )
            && \hash_equals(
                (string)$receipt['prior_authority_digest'],
                \hash('sha256', $this->canonicalJson($prior)),
            )
            && \is_array($prior['enrollment_projection'] ?? null)
            && $this->enrollmentProjectionMatchesTransactionAuthority(
                (array)$prior['enrollment_projection'],
                $transaction,
                $transactionId,
            );
    }

    /**
     * A terminal enrollment remains historical authorization evidence after
     * revocation or identity rotation removes its live map entry. Accept that
     * history only when a later monotonic tombstone and its immutable
     * transaction facts prove the exact retired enrollment.
     *
     * @param array<string,mixed> $enrollmentTransaction
     * @param array<string,mixed> $tombstones
     * @param array<string,mixed> $rotationTransactions
     * @param array<string,mixed> $securityTransactions
     * @return array<string,mixed>|null
     */
    private function retiredEnrollmentClosureSnapshot(
        array $enrollmentTransaction,
        array $tombstones,
        array $rotationTransactions,
        array $securityTransactions,
    ): ?array {
        $projectUuid = (string)($enrollmentTransaction['project_uuid'] ?? '');
        $enrollmentGeneration = (int)(
            $enrollmentTransaction['security_generation'] ?? 0
        );
        $tombstone = $tombstones['project:' . $projectUuid] ?? null;
        if (!\is_array($tombstone)
            || (int)($tombstone['generation'] ?? 0) <= $enrollmentGeneration
        ) {
            return null;
        }
        $kind = (string)($tombstone['kind'] ?? '');
        if (\hash_equals('project_identity_rotation', $kind)) {
            $rotationId = (string)($tombstone['rotation_id'] ?? '');
            $rotation = $rotationTransactions[$rotationId] ?? null;
            $retiredProjection = \is_array($rotation)
                ? ($rotation['retired_enrollment_snapshot'] ?? null)
                : null;
            if (!\is_array($rotation)
                || !\hash_equals(
                    'FINALIZED',
                    (string)($rotation['phase'] ?? ''),
                )
                || !\is_array($retiredProjection)
                || !\hash_equals(
                    $projectUuid,
                    (string)($rotation['old_project_uuid'] ?? ''),
                )
                || !\hash_equals(
                    (string)($tombstone['to_project_uuid'] ?? ''),
                    (string)($rotation['new_project_uuid'] ?? ''),
                )
                || (int)$tombstone['generation']
                    !== (int)($rotation['security_generation'] ?? 0)
                || !\hash_equals(
                    (string)($enrollmentTransaction['credential_id'] ?? ''),
                    (string)($rotation['old_credential_id'] ?? ''),
                )
                || !\hash_equals(
                    (string)($rotation['old_credential_id'] ?? ''),
                    (string)($tombstone['credential_id'] ?? ''),
                )
                || !\hash_equals(
                    \hash(
                        'sha256',
                        $this->canonicalJson($retiredProjection),
                    ),
                    (string)(
                        $rotation['retired_enrollment_snapshot_digest'] ?? ''
                    ),
                )
            ) {
                return null;
            }
            $historical = $this->enrollmentSnapshotFromTransaction(
                $enrollmentTransaction,
            );
            try {
                $historicalProjection =
                    $this->enrollmentSecurityProjection($historical);
            } catch (\Throwable) {
                return null;
            }
            return \hash_equals(
                $this->canonicalJson($retiredProjection),
                $this->canonicalJson($historicalProjection),
            ) ? $historical : null;
        }
        if (!\hash_equals('project_revoke', $kind)
            || !\hash_equals(
                $projectUuid,
                (string)($tombstone['project_uuid'] ?? ''),
            )
            || !\hash_equals(
                (string)($enrollmentTransaction['credential_id'] ?? ''),
                (string)($tombstone['credential_id'] ?? ''),
            )
        ) {
            return null;
        }
        $legacyTransactionMatched = false;
        foreach ($securityTransactions as $securityTransaction) {
            if (!\is_array($securityTransaction)
                || !\hash_equals(
                    'PROJECT_REVOKE',
                    (string)($securityTransaction['kind'] ?? ''),
                )
                || !\in_array(
                    (string)($securityTransaction['phase'] ?? ''),
                    ['LEDGER_COMMITTED', 'BROKER_COMMITTED', 'COMMITTED'],
                    true,
                )
                || (int)($securityTransaction['assigned_generation'] ?? 0)
                    !== (int)$tombstone['generation']
            ) {
                continue;
            }
            if ((int)($securityTransaction['schema_version'] ?? 1) < 2) {
                $legacyTransactionMatched = true;
            }
            $facts = $securityTransaction['controller_facts'] ?? null;
            $snapshot = \is_array($facts) ? ($facts['enrollment'] ?? null) : null;
            if (\is_array($snapshot)
                && \hash_equals(
                    $projectUuid,
                    (string)($snapshot['project_uuid'] ?? ''),
                )
            ) {
                return $snapshot;
            }
        }
        if ($legacyTransactionMatched) {
            // Legacy revoke transactions did not retain Controller facts. An
            // explicit matching legacy transaction plus the strictly newer
            // credential-bound tombstone still proves retirement.
            return $this->enrollmentSnapshotFromTransaction(
                $enrollmentTransaction,
            );
        }
        return null;
    }

    /**
     * @param array<string,mixed> $transaction
     * @return array<string,mixed>
     */
    private function enrollmentSnapshotFromTransaction(array $transaction): array
    {
        return [
            'project_uuid' => (string)($transaction['project_uuid'] ?? ''),
            'project_root' => (string)($transaction['project_root'] ?? ''),
            'certificate_roots' => (array)(
                $transaction['certificate_roots'] ?? []
            ),
            'allowed_domains' => (array)($transaction['allowed_domains'] ?? []),
            'owner' => (array)($transaction['owner'] ?? []),
            'capabilities' => (array)($transaction['capabilities'] ?? []),
            'desired_digest' => (string)(
                $transaction['authenticated_desired_digest'] ?? ''
            ),
            'enrollment_transaction_id' => (string)(
                $transaction['transaction_id'] ?? ''
            ),
            'native_authorization_transaction_id' => (string)(
                $transaction['transaction_id'] ?? ''
            ),
            'native_authorization_intent_digest' => (string)(
                $transaction['authenticated_desired_digest'] ?? ''
            ),
            'client_request_digest' => (string)(
                $transaction['request_digest'] ?? ''
            ),
            'authenticated_peer_digest' => (string)(
                $transaction['authenticated_peer_digest'] ?? ''
            ),
            'credential_id' => (string)($transaction['credential_id'] ?? ''),
            'credential_secret' => (string)(
                $transaction['credential_secret'] ?? ''
            ),
            'credential_generation' => (int)(
                $transaction['credential_generation'] ?? 0
            ),
            'security_generation' => (int)(
                $transaction['security_generation'] ?? 0
            ),
        ];
    }

    /**
     * @param array<string,mixed> $transactions
     */
    private function validEnrollmentControllerGenerations(
        array $transactions,
    ): bool {
        $allocated = [];
        foreach ($transactions as $transactionId => $transaction) {
            if (!\is_array($transaction)) {
                return false;
            }
            $schema = (int)($transaction['schema_version'] ?? 1);
            $hasGeneration = \array_key_exists(
                'controller_generation',
                $transaction,
            );
            $hasPending = \array_key_exists(
                'generation_audit_pending',
                $transaction,
            );
            $hasReplayKey = \array_key_exists(
                'generation_audit_replay_key',
                $transaction,
            );
            if (!\in_array($schema, [1, 2, 3], true)
                || ($hasGeneration
                    && !\is_int($transaction['controller_generation']))
                || ($hasPending
                    && !\is_bool($transaction['generation_audit_pending']))
                || ($hasReplayKey
                    && !\is_string($transaction['generation_audit_replay_key']))
                || ($schema >= 2
                    && (!$hasGeneration || !$hasPending || !$hasReplayKey))
            ) {
                return false;
            }
            $generation = (int)($transaction['controller_generation'] ?? 0);
            $pending = ($transaction['generation_audit_pending'] ?? false) === true;
            $replayKey = (string)(
                $transaction['generation_audit_replay_key'] ?? ''
            );
            $phase = (string)($transaction['phase'] ?? '');
            if ($generation < 0
                || ($generation > 0
                    && !\in_array(
                        $phase,
                        ['COMMITTED', 'SUPERSEDED'],
                        true,
                    ))
                || ($pending && ($generation < 1 || !\hash_equals('COMMITTED', $phase)))
                || ($generation > 0
                    && !\hash_equals(
                        'enroll:' . (string)$transactionId . ':' . $generation,
                        $replayKey,
                    ))
                || ($generation === 0 && $replayKey !== '')
                || ($schema >= 2
                    && \in_array(
                        $phase,
                        ['COMMITTED', 'SUPERSEDED'],
                        true,
                    )
                    && $generation < 1)
            ) {
                return false;
            }
            if ($generation < 1) {
                continue;
            }
            if (isset($allocated[$generation])
                && !\hash_equals((string)$allocated[$generation], (string)$transactionId)
            ) {
                return false;
            }
            $allocated[$generation] = (string)$transactionId;
        }
        return true;
    }

    /**
     * @param array<string,mixed> $transactions
     * @param array<string,mixed> $enrollments
     */
    private function validProjectIdentityRotationTransactions(
        array $transactions,
        array $enrollments,
        array $tombstones,
        array $securityTransactions,
        array $enrollmentTransactions,
    ): bool {
        if ($this->activeRotationTransactionCount($transactions)
            > self::MAX_ROTATION_TRANSACTIONS
        ) {
            return false;
        }
        $activeIdentities = [];
        $securityGenerations = [];
        try {
            foreach ($transactions as $rotationId => $transaction) {
                if (!\is_array($transaction)
                    || !$this->validProjectIdentityRotationTransaction(
                        (string)$rotationId,
                        $transaction,
                        $enrollments,
                        $tombstones,
                        $transactions,
                        $securityTransactions,
                        $enrollmentTransactions,
                    )
                ) {
                    return false;
                }
                $phase = (string)$transaction['phase'];
                if (!\in_array($phase, ['ABORTED', 'FINALIZED'], true)) {
                    foreach ([
                        (string)$transaction['old_project_uuid'],
                        (string)$transaction['new_project_uuid'],
                    ] as $projectUuid) {
                        if (isset($activeIdentities[$projectUuid])) {
                            return false;
                        }
                        $activeIdentities[$projectUuid] = (string)$rotationId;
                    }
                }
                $securityGeneration = (int)(
                    $transaction['security_generation'] ?? 0
                );
                if ($securityGeneration > 0) {
                    if (isset($securityGenerations[$securityGeneration])) {
                        return false;
                    }
                    $securityGenerations[$securityGeneration] = (string)$rotationId;
                }
            }
        } catch (\Throwable) {
            return false;
        }
        return true;
    }

    /**
     * @param array<string,mixed> $transaction
     * @param array<string,mixed> $enrollments
     */
    private function validProjectIdentityRotationTransaction(
        string $rotationId,
        array $transaction,
        array $enrollments,
        array $tombstones,
        array $rotationTransactions,
        array $securityTransactions,
        array $enrollmentTransactions,
    ): bool {
        $schema = (int)($transaction['schema_version'] ?? 1);
        $phase = (string)($transaction['phase'] ?? '');
        $oldUuid = (string)($transaction['old_project_uuid'] ?? '');
        $newUuid = (string)($transaction['new_project_uuid'] ?? '');
        $projectRoot = (string)($transaction['project_root'] ?? '');
        $requestFacts = [
            'schema_version' => 1,
            'protocol' => self::PROTOCOL,
            'rotation_id' => $rotationId,
            'old_project_uuid' => $oldUuid,
            'new_project_uuid' => $newUuid,
            'project_root' => $projectRoot,
        ];
        $requestDigest = \hash(
            'sha256',
            $this->canonicalJson($requestFacts),
        );
        $expectedIdempotency = \substr(\hash(
            'sha256',
            $oldUuid . ':rotate:' . $newUuid . ':' . $requestDigest,
        ), 0, 40);
        if (!\in_array($schema, [1, 2], true)
            || \preg_match('/\A[a-f0-9]{32}\z/D', $rotationId) !== 1
            || !\hash_equals(
                $rotationId,
                (string)($transaction['rotation_id'] ?? ''),
            )
            || !\hash_equals(
                self::PROTOCOL,
                (string)($transaction['protocol'] ?? ''),
            )
            || !$this->validProjectUuid($oldUuid)
            || !$this->validProjectUuid($newUuid)
            || \hash_equals($oldUuid, $newUuid)
            || $projectRoot === ''
            || \strlen($projectRoot) > 4096
            || !\hash_equals(
                $requestDigest,
                (string)($transaction['request_digest'] ?? ''),
            )
            || !\hash_equals(
                $expectedIdempotency,
                (string)($transaction['idempotency_key'] ?? ''),
            )
            || !\in_array($phase, [
                'PREPARED',
                'NATIVE_PREPARED',
                'LEDGER_COMMITTED',
                'BROKER_COMMITTED',
                'CONTROLLER_COMMITTED',
                'FINALIZED',
                'ABORTED',
            ], true)
            || !\is_array($transaction['owner'] ?? null)
            || \preg_match(
                '/\A[a-f0-9]{32}\z/D',
                (string)($transaction['old_credential_id'] ?? ''),
            ) !== 1
            || \preg_match(
                '/\A[a-f0-9]{32}\z/D',
                (string)($transaction['new_credential_id'] ?? ''),
            ) !== 1
            || !\is_int($transaction['new_credential_generation'] ?? null)
            || (int)$transaction['new_credential_generation'] < 2
            || !\is_int($transaction['security_generation'] ?? null)
            || (int)$transaction['security_generation'] < 0
        ) {
            return false;
        }
        $this->brokerOwnerIdentity((array)$transaction['owner']);
        if (!\in_array($phase, ['ABORTED', 'FINALIZED'], true)) {
            if (\preg_match(
                    '/\A[a-f0-9]{64}\z/D',
                    (string)($transaction['new_credential_secret'] ?? ''),
                ) !== 1
                || !$this->validProjectIdentityRotationEnrollmentSnapshot(
                    $transaction,
                )
            ) {
                return false;
            }
        }
        if ((\hash_equals('FINALIZED', $phase)
                && (\array_key_exists('new_credential_secret', $transaction)
                    || \array_key_exists('old_enrollment_snapshot', $transaction)
                    || \array_key_exists('old_project_snapshot', $transaction)))
            || (!\hash_equals('FINALIZED', $phase)
                && (\array_key_exists(
                        'retired_enrollment_snapshot',
                        $transaction,
                    )
                    || \array_key_exists(
                        'final_enrollment_snapshot',
                        $transaction,
                    )))
        ) {
            return false;
        }
        if ($schema < 2) {
            // Legacy records are admitted only for deterministic abort or
            // roll-forward migration during bootstrap.
            return true;
        }

        $securityGeneration = (int)$transaction['security_generation'];
        $controllerGeneration = $transaction['controller_generation'] ?? null;
        $controllerPhase = (string)($transaction['controller_phase'] ?? '');
        $auditPending = $transaction['generation_audit_pending'] ?? null;
        $auditReplayKey = $transaction['generation_audit_replay_key'] ?? null;
        $routeFacts = $transaction['route_migration_facts'] ?? null;
        $routeFactsDigest = $transaction['route_migration_facts_digest'] ?? null;
        $publicationId = $transaction['publication_transaction_id'] ?? null;
        $publicationAttempts = $transaction['publication_attempts'] ?? null;
        $prepareDeadline = $transaction['prepare_deadline_monotonic'] ?? null;
        if (!\is_int($controllerGeneration)
            || $controllerGeneration < 0
            || !\in_array($controllerPhase, [
                'PENDING',
                'APPLIED',
                'PUBLICATION_PENDING',
                'CONTROLLER_COMMITTED',
            ], true)
            || !\is_bool($auditPending)
            || !\is_string($auditReplayKey)
            || !\is_array($routeFacts)
            || !\is_string($routeFactsDigest)
            || !\is_string($publicationId)
            || !\is_array($publicationAttempts)
            || \preg_match(
                '/\A[a-f0-9]{64}\z/D',
                (string)($transaction['prepare_boot_id'] ?? ''),
            ) !== 1
            || (!\is_int($prepareDeadline) && !\is_float($prepareDeadline))
            || !\is_finite((float)$prepareDeadline)
            || (float)$prepareDeadline <= 0.0
            || !\is_int($transaction['prepare_expires_at_unix'] ?? null)
            || (int)$transaction['prepare_expires_at_unix'] < 1
            || \count($publicationAttempts) > 16
        ) {
            return false;
        }
        $seenAttempts = [];
        foreach ($publicationAttempts as $attempt) {
            if (!\is_string($attempt)
                || \preg_match('/\A[a-f0-9]{32}\z/D', $attempt) !== 1
                || isset($seenAttempts[$attempt])
            ) {
                return false;
            }
            $seenAttempts[$attempt] = true;
        }
        if (($controllerGeneration === 0
                && ($auditPending !== false
                    || $auditReplayKey !== ''
                    || !\hash_equals('PENDING', $controllerPhase)))
            || ($controllerGeneration > 0
                && !\hash_equals(
                    'rotation:' . $rotationId . ':' . $controllerGeneration,
                    $auditReplayKey,
                ))
            || ($controllerGeneration > 0
                && \hash_equals('PENDING', $controllerPhase)
                && $auditPending !== true)
            || (\in_array(
                    $controllerPhase,
                    ['PUBLICATION_PENDING', 'CONTROLLER_COMMITTED'],
                    true,
                ) && $auditPending !== false)
            || ($publicationId === ''
                && \in_array($controllerPhase, [
                    'APPLIED',
                    'PUBLICATION_PENDING',
                    'CONTROLLER_COMMITTED',
                ], true))
            || ($publicationId !== ''
                && (\preg_match('/\A[a-f0-9]{32}\z/D', $publicationId) !== 1
                    || !isset($seenAttempts[$publicationId])
                    || !\in_array($controllerPhase, [
                        'PENDING',
                        'APPLIED',
                        'PUBLICATION_PENDING',
                        'CONTROLLER_COMMITTED',
                    ], true)))
        ) {
            return false;
        }

        $preCommit = \in_array($phase, ['PREPARED', 'NATIVE_PREPARED'], true);
        $ledgerAuthorized = \in_array($phase, [
            'LEDGER_COMMITTED',
            'BROKER_COMMITTED',
            'CONTROLLER_COMMITTED',
            'FINALIZED',
        ], true);
        $retiredSecurityGeneration = (int)(
            \hash_equals('FINALIZED', $phase)
                ? ($transaction['retired_enrollment_snapshot']
                    ['security_generation'] ?? 0)
                : ($transaction['old_enrollment_snapshot']
                    ['security_generation'] ?? 0)
        );
        if (($phase === 'PREPARED' && $securityGeneration !== 0)
            || ($phase === 'NATIVE_PREPARED' && $securityGeneration < 1)
            || ($ledgerAuthorized && $securityGeneration < 1)
            || ($preCommit
                && ($routeFacts !== [] || $routeFactsDigest !== ''))
            || ($phase === 'ABORTED'
                && ($controllerGeneration !== 0
                    || $publicationId !== ''
                    || $routeFacts !== []
                    || $routeFactsDigest !== ''))
            || ($ledgerAuthorized
                    && (!$this->validProjectIdentityRotationRouteFacts(
                        $routeFacts,
                        $oldUuid,
                        $projectRoot,
                        $retiredSecurityGeneration,
                    )
                    || \preg_match(
                        '/\A[a-f0-9]{64}\z/D',
                        $routeFactsDigest,
                    ) !== 1
                    || !\hash_equals(
                        $routeFactsDigest,
                        \hash('sha256', $this->canonicalJson($routeFacts)),
                    )
                    || \preg_match(
                        '/\A[a-f0-9]{64}\z/D',
                        (string)($transaction['commit_proof_digest'] ?? ''),
                    ) !== 1))
            || ($securityGeneration > 0
                && \preg_match(
                    '/\A[a-f0-9]{64}\z/D',
                    (string)($transaction['native_registry_digest'] ?? ''),
                ) !== 1)
            || (\in_array($phase, [
                    'BROKER_COMMITTED',
                    'CONTROLLER_COMMITTED',
                    'FINALIZED',
                ], true)
                && \preg_match(
                    '/\A[a-f0-9]{64}\z/D',
                    (string)($transaction['native_tombstone_digest'] ?? ''),
                ) !== 1)
        ) {
            return false;
        }
        if (\in_array($phase, [
                'PREPARED',
                'NATIVE_PREPARED',
                'LEDGER_COMMITTED',
            ], true)
            && ($controllerGeneration !== 0
                || !\hash_equals('PENDING', $controllerPhase)
                || $publicationId !== '')
        ) {
            return false;
        }
        if ($phase === 'BROKER_COMMITTED'
            && \hash_equals('CONTROLLER_COMMITTED', $controllerPhase)
        ) {
            return false;
        }
        if (\in_array($phase, ['CONTROLLER_COMMITTED', 'FINALIZED'], true)
            && ($controllerGeneration < 1
                || !\hash_equals('CONTROLLER_COMMITTED', $controllerPhase)
                || $auditPending !== false
                || \preg_match(
                    '/\A[a-f0-9]{32}\z/D',
                    $publicationId,
                ) !== 1
                || !\is_int($transaction['publication_generation'] ?? null)
                || (int)$transaction['publication_generation']
                    < $controllerGeneration
                || \preg_match(
                    '/\A[a-f0-9]{64}\z/D',
                    (string)($transaction['publication_config_digest'] ?? ''),
                ) !== 1)
        ) {
            return false;
        }
        if (\in_array($controllerPhase, [
                'APPLIED',
                'PUBLICATION_PENDING',
                'CONTROLLER_COMMITTED',
            ], true)
            && (\hash_equals('FINALIZED', $phase)
                ? !$this->validFinalizedProjectIdentityRotationEndpoint(
                    $transaction,
                    $enrollments,
                    $tombstones,
                    $rotationTransactions,
                    $securityTransactions,
                    $enrollmentTransactions,
                )
                : !$this->validProjectIdentityRotationNewEnrollment(
                    $transaction,
                    $enrollments,
                ))
        ) {
            return false;
        }
        return true;
    }

    /** @param array<string,mixed> $transaction */
    private function validProjectIdentityRotationEnrollmentSnapshot(
        array $transaction,
    ): bool {
        $snapshot = $transaction['old_enrollment_snapshot'] ?? null;
        if (!\is_array($snapshot)) {
            return false;
        }
        $desired = [
            'project_uuid' => (string)($snapshot['project_uuid'] ?? ''),
            'project_root' => (string)($snapshot['project_root'] ?? ''),
            'certificate_roots' => (array)($snapshot['certificate_roots'] ?? []),
            'allowed_domains' => (array)($snapshot['allowed_domains'] ?? []),
            'owner' => (array)($snapshot['owner'] ?? []),
            'capabilities' => (array)($snapshot['capabilities'] ?? []),
        ];
        return \hash_equals(
                (string)$transaction['old_project_uuid'],
                $desired['project_uuid'],
            )
            && $this->validEnrollmentSecuritySnapshot(
                $snapshot,
                (string)$transaction['old_project_uuid'],
            )
            && \hash_equals(
                (string)$transaction['project_root'],
                $desired['project_root'],
            )
            && \hash_equals(
                $this->canonicalJson((array)$transaction['owner']),
                $this->canonicalJson($desired['owner']),
            )
            && \hash_equals(
                (string)$transaction['old_credential_id'],
                (string)($snapshot['credential_id'] ?? ''),
            )
            && \preg_match(
                '/\A[a-f0-9]{64}\z/D',
                (string)($snapshot['credential_secret'] ?? ''),
            ) === 1
            && (int)($snapshot['credential_generation'] ?? 0) >= 1
            && (int)$transaction['new_credential_generation']
                === (int)$snapshot['credential_generation'] + 1
            && \hash_equals(
                (string)($snapshot['desired_digest'] ?? ''),
                \hash('sha256', $this->canonicalJson($desired)),
            );
    }

    /**
     * @param list<array<string,mixed>> $routeFacts
     */
    private function validProjectIdentityRotationRouteFacts(
        array $routeFacts,
        string $oldUuid,
        string $projectRoot,
        int $enrollmentSecurityGeneration,
    ): bool {
        if (!\array_is_list($routeFacts)
            || \count($routeFacts) > self::MAX_ROUTES_PER_PROJECT
        ) {
            return false;
        }
        $previousRouteId = '';
        $domains = [];
        foreach ($routeFacts as $route) {
            if (!\is_array($route)
                || !$this->validFrozenSecurityRoute(
                    $route,
                    $oldUuid,
                    $projectRoot,
                    $enrollmentSecurityGeneration,
                    false,
                )
            ) {
                return false;
            }
            $domain = (string)($route['domain'] ?? '');
            if ($domain === ''
                || !\hash_equals($domain, $this->normalizeDomain($domain))
            ) {
                return false;
            }
            $routeId = (string)($route['route_id'] ?? '');
            if (!\hash_equals(
                    $this->canonicalRouteId($oldUuid, $domain),
                    $routeId,
                )
                || ($previousRouteId !== ''
                    && \strcmp($previousRouteId, $routeId) >= 0)
                || isset($domains[$domain])
            ) {
                return false;
            }
            $previousRouteId = $routeId;
            $domains[$domain] = true;
        }
        return true;
    }

    /**
     * @param array<string,mixed> $transaction
     * @param array<string,mixed> $enrollments
     */
    private function validProjectIdentityRotationNewEnrollment(
        array $transaction,
        array $enrollments,
    ): bool {
        $newUuid = (string)$transaction['new_project_uuid'];
        $enrollment = $enrollments[$newUuid] ?? null;
        if (!\is_array($enrollment)) {
            return false;
        }
        $phase = (string)($transaction['phase'] ?? '');
        $rotationMarker = (string)($enrollment['rotation_id'] ?? '');
        $rotationMarkerValid = \hash_equals('FINALIZED', $phase)
            ? $rotationMarker === ''
            : \hash_equals(
                (string)$transaction['rotation_id'],
                $rotationMarker,
            );
        $desired = [
            'project_uuid' => (string)($enrollment['project_uuid'] ?? ''),
            'project_root' => (string)($enrollment['project_root'] ?? ''),
            'certificate_roots' => (array)($enrollment['certificate_roots'] ?? []),
            'allowed_domains' => (array)($enrollment['allowed_domains'] ?? []),
            'owner' => (array)($enrollment['owner'] ?? []),
            'capabilities' => (array)($enrollment['capabilities'] ?? []),
        ];
        $credentialSecret = (string)(
            $enrollment['credential_secret'] ?? ''
        );
        $expectedCommitProof = \preg_match(
            '/\A[a-f0-9]{64}\z/D',
            $credentialSecret,
        ) === 1 ? \hash_hmac(
            'sha256',
            $this->canonicalJson(
                $this->projectIdentityRotationCommitFacts($transaction),
            ),
            $credentialSecret,
        ) : '';
        return $this->validEnrollmentSecuritySnapshot($enrollment, $newUuid)
            && \hash_equals($newUuid, $desired['project_uuid'])
            && \hash_equals(
                (string)$transaction['project_root'],
                $desired['project_root'],
            )
            && \hash_equals(
                (string)$transaction['new_credential_id'],
                (string)($enrollment['credential_id'] ?? ''),
            )
            && (int)$transaction['new_credential_generation']
                === (int)($enrollment['credential_generation'] ?? 0)
            && (int)$transaction['security_generation']
                === (int)($enrollment['security_generation'] ?? 0)
            && $rotationMarkerValid
            && \hash_equals(
                (string)$transaction['rotation_id'],
                (string)(
                    $enrollment['native_authorization_transaction_id'] ?? ''
                ),
            )
            && \hash_equals(
                $this->nativeProjectIdentityRotationIntent($transaction),
                (string)(
                    $enrollment['native_authorization_intent_digest'] ?? ''
                ),
            )
            && \hash_equals(
                (string)($enrollment['desired_digest'] ?? ''),
                \hash('sha256', $this->canonicalJson($desired)),
            )
            && \hash_equals(
                (string)($transaction['commit_proof_digest'] ?? ''),
                \hash('sha256', $expectedCommitProof),
            );
    }

    /**
     * A finalized A→B rotation remains verifiable after B is later revoked or
     * rotated to C. The terminal snapshots contain no credential secret; the
     * current live enrollment or the exact later tombstone transaction must
     * supply that secret and close the original commit proof.
     *
     * @param array<string,mixed> $transaction
     * @param array<string,mixed> $enrollments
     * @param array<string,mixed> $tombstones
     * @param array<string,mixed> $rotationTransactions
     * @param array<string,mixed> $securityTransactions
     */
    private function validFinalizedProjectIdentityRotationEndpoint(
        array $transaction,
        array $enrollments,
        array $tombstones,
        array $rotationTransactions,
        array $securityTransactions,
        array $enrollmentTransactions,
    ): bool {
        $oldUuid = (string)$transaction['old_project_uuid'];
        $newUuid = (string)$transaction['new_project_uuid'];
        $retired = $transaction['retired_enrollment_snapshot'] ?? null;
        $final = $transaction['final_enrollment_snapshot'] ?? null;
        if (!\is_array($retired)
            || !\is_array($final)
            || !$this->validEnrollmentSecurityProjection($retired, $oldUuid)
            || !$this->validEnrollmentSecurityProjection($final, $newUuid)
            || !\hash_equals(
                \hash('sha256', $this->canonicalJson($retired)),
                (string)(
                    $transaction['retired_enrollment_snapshot_digest'] ?? ''
                ),
            )
            || !\hash_equals(
                \hash('sha256', $this->canonicalJson($final)),
                (string)(
                    $transaction['final_enrollment_snapshot_digest'] ?? ''
                ),
            )
            || !\hash_equals(
                (string)$transaction['project_root'],
                (string)$retired['project_root'],
            )
            || !\hash_equals(
                (string)$transaction['project_root'],
                (string)$final['project_root'],
            )
            || !\hash_equals(
                (string)$transaction['old_credential_id'],
                (string)$retired['credential_id'],
            )
            || !\hash_equals(
                (string)$transaction['new_credential_id'],
                (string)$final['credential_id'],
            )
            || (int)$transaction['new_credential_generation']
                !== (int)$final['credential_generation']
            || (int)$transaction['new_credential_generation']
                !== (int)$retired['credential_generation'] + 1
            || (int)$transaction['security_generation']
                !== (int)$final['security_generation']
            || !\hash_equals(
                (string)$transaction['rotation_id'],
                (string)$final['native_authorization_transaction_id'],
            )
            || !\hash_equals(
                $this->nativeProjectIdentityRotationIntent($transaction),
                (string)$final['native_authorization_intent_digest'],
            )
        ) {
            return false;
        }
        foreach ([
            'certificate_roots',
            'allowed_domains',
            'owner',
            'capabilities',
        ] as $field) {
            if (!\hash_equals(
                $this->canonicalJson((array)$retired[$field]),
                $this->canonicalJson((array)$final[$field]),
            )) {
                return false;
            }
        }
        if (\array_key_exists('superseded_by_enrollment', $transaction)) {
            return $this->validRotationSupersededByEnrollment(
                $transaction,
                $final,
                $enrollmentTransactions,
            );
        }
        $liveEnrollment = $enrollments[$newUuid] ?? null;
        if (\is_array($liveEnrollment)) {
            return $this->projectIdentityRotationProjectionMatchesEnrollment(
                $transaction,
                $final,
                $liveEnrollment,
            );
        }
        $tombstone = $tombstones['project:' . $newUuid] ?? null;
        if (!\is_array($tombstone)
            || (int)($tombstone['generation'] ?? 0)
                <= (int)$transaction['security_generation']
        ) {
            return false;
        }
        if (\hash_equals(
            'project_revoke',
            (string)($tombstone['kind'] ?? ''),
        )) {
            foreach ($securityTransactions as $securityTransaction) {
                if (!\is_array($securityTransaction)
                    || !\hash_equals(
                        'PROJECT_REVOKE',
                        (string)($securityTransaction['kind'] ?? ''),
                    )
                    || (int)($securityTransaction['assigned_generation'] ?? 0)
                        !== (int)$tombstone['generation']
                    || !\in_array(
                        (string)($securityTransaction['phase'] ?? ''),
                        ['LEDGER_COMMITTED', 'BROKER_COMMITTED'],
                        true,
                    )
                    || (\hash_equals(
                            'LEDGER_COMMITTED',
                            (string)($securityTransaction['phase'] ?? ''),
                        )
                        ? !\hash_equals(
                            'PENDING',
                            (string)(
                                $securityTransaction['controller_phase'] ?? ''
                            ),
                        )
                        : !\in_array(
                            (string)(
                                $securityTransaction['controller_phase'] ?? ''
                            ),
                            [
                                'PENDING',
                                'APPLIED',
                                'PUBLICATION_PENDING',
                                'CONTROLLER_COMMITTED',
                            ],
                            true,
                        ))
                ) {
                    continue;
                }
                $facts = $securityTransaction['controller_facts'] ?? null;
                $retiredEnrollment = \is_array($facts)
                    ? ($facts['enrollment'] ?? null)
                    : null;
                return \is_array($retiredEnrollment)
                    && \hash_equals(
                        $newUuid,
                        (string)($facts['project_uuid'] ?? ''),
                    )
                    && \hash_equals(
                        (string)$final['credential_id'],
                        (string)($tombstone['credential_id'] ?? ''),
                    )
                    && $this->projectIdentityRotationProjectionMatchesEnrollment(
                        $transaction,
                        $final,
                        $retiredEnrollment,
                    );
            }
            return false;
        }
        if (!\hash_equals(
            'project_identity_rotation',
            (string)($tombstone['kind'] ?? ''),
        )) {
            return false;
        }
        $successorRotationId = (string)($tombstone['rotation_id'] ?? '');
        $successor = $rotationTransactions[$successorRotationId] ?? null;
        $successorRetired = \is_array($successor)
            ? ($successor['retired_enrollment_snapshot'] ?? null)
            : null;
        return \is_array($successor)
            && \is_array($successorRetired)
            && \hash_equals('FINALIZED', (string)($successor['phase'] ?? ''))
            && \hash_equals(
                $newUuid,
                (string)($successor['old_project_uuid'] ?? ''),
            )
            && (int)($successor['security_generation'] ?? 0)
                === (int)$tombstone['generation']
            && \hash_equals(
                $successorRotationId,
                (string)($successor['rotation_id'] ?? ''),
            )
            && \hash_equals(
                \hash('sha256', $this->canonicalJson($successorRetired)),
                (string)(
                    $successor['retired_enrollment_snapshot_digest'] ?? ''
                ),
            )
            && \hash_equals(
                $this->canonicalJson($final),
                $this->canonicalJson($successorRetired),
            );
    }

    /**
     * @param array<string,mixed> $transaction
     * @param array<string,mixed> $finalProjection
     * @param array<string,mixed> $enrollmentTransactions
     */
    private function validRotationSupersededByEnrollment(
        array $transaction,
        array $finalProjection,
        array $enrollmentTransactions,
    ): bool {
        $receipt = $transaction['superseded_by_enrollment'] ?? null;
        if (!\is_array($receipt)
            || \array_keys($receipt) !== [
                'schema_version',
                'transaction_id',
                'project_uuid',
                'security_generation',
                'credential_generation',
                'desired_digest',
                'prior_authority_digest',
            ]
            || (int)($receipt['schema_version'] ?? 0) !== 1
            || !\hash_equals(
                (string)($transaction['new_project_uuid'] ?? ''),
                (string)($receipt['project_uuid'] ?? ''),
            )
            || !\is_int($receipt['security_generation'] ?? null)
            || (int)$receipt['security_generation']
                <= (int)($transaction['security_generation'] ?? 0)
            || !\is_int($receipt['credential_generation'] ?? null)
            || (int)$receipt['credential_generation']
                !== (int)($transaction['new_credential_generation'] ?? 0) + 1
            || \preg_match(
                '/\A[a-f0-9]{64}\z/D',
                (string)($receipt['desired_digest'] ?? ''),
            ) !== 1
            || \preg_match(
                '/\A[a-f0-9]{64}\z/D',
                (string)($receipt['prior_authority_digest'] ?? ''),
            ) !== 1
            || !\is_string($transaction['superseded_at'] ?? null)
            || (string)$transaction['superseded_at'] === ''
        ) {
            return false;
        }
        $successorId = (string)($receipt['transaction_id'] ?? '');
        $successor = $enrollmentTransactions[$successorId] ?? null;
        $prior = \is_array($successor)
            ? ($successor['prior_authority'] ?? null)
            : null;
        return \preg_match('/\A[a-f0-9]{32}\z/D', $successorId) === 1
            && \is_array($successor)
            && \in_array(
                (string)($successor['phase'] ?? ''),
                [
                    'LEDGER_COMMITTED',
                    'BROKER_COMMITTED',
                    'COMMITTED',
                    'SUPERSEDED',
                ],
                true,
            )
            && \is_array($prior)
            && \hash_equals('rotation', (string)($prior['family'] ?? ''))
            && \hash_equals(
                (string)($transaction['rotation_id'] ?? ''),
                (string)($prior['transaction_id'] ?? ''),
            )
            && \is_array($prior['enrollment_projection'] ?? null)
            && \hash_equals(
                $this->canonicalJson($finalProjection),
                $this->canonicalJson((array)$prior[
                    'enrollment_projection'
                ]),
            )
            && \hash_equals(
                (string)$receipt['prior_authority_digest'],
                \hash('sha256', $this->canonicalJson($prior)),
            )
            && \hash_equals(
                (string)$receipt['project_uuid'],
                (string)($successor['project_uuid'] ?? ''),
            )
            && (int)$receipt['security_generation']
                === (int)($successor['security_generation'] ?? 0)
            && (int)$receipt['credential_generation']
                === (int)($successor['credential_generation'] ?? 0)
            && \hash_equals(
                (string)$receipt['desired_digest'],
                (string)(
                    $successor['authenticated_desired_digest'] ?? ''
                ),
            );
    }

    /**
     * @param array<string,mixed> $transaction
     * @param array<string,mixed> $projection
     * @param array<string,mixed> $enrollment
     */
    private function projectIdentityRotationProjectionMatchesEnrollment(
        array $transaction,
        array $projection,
        array $enrollment,
    ): bool {
        try {
            $currentProjection = $this->enrollmentSecurityProjection($enrollment);
        } catch (\Throwable) {
            return false;
        }
        $secret = (string)($enrollment['credential_secret'] ?? '');
        $proof = \preg_match('/\A[a-f0-9]{64}\z/D', $secret) === 1
            ? \hash_hmac(
                'sha256',
                $this->canonicalJson(
                    $this->projectIdentityRotationCommitFacts($transaction),
                ),
                $secret,
            )
            : '';
        return \hash_equals(
                $this->canonicalJson($projection),
                $this->canonicalJson($currentProjection),
            )
            && \hash_equals(
                (string)($transaction['commit_proof_digest'] ?? ''),
                \hash('sha256', $proof),
            );
    }

    /** @param array<string,mixed> $transactions */
    private function validGenericSecurityTransactions(array $transactions): bool
    {
        if ($this->activeGenericSecurityTransactionCount($transactions)
            > self::MAX_SECURITY_TRANSACTIONS
        ) {
            return false;
        }
        foreach ($transactions as $transactionId => $transaction) {
            if (!\is_array($transaction)) {
                return false;
            }
            if ((int)($transaction['schema_version'] ?? 1) < 2) {
                // Legacy transactions are accepted only so bootstrap can
                // deterministically abort an uncommitted reservation or
                // migrate a reconstructable committed after-image.
                if (!\in_array(
                        (string)($transaction['phase'] ?? ''),
                        ['PREPARED', 'RESERVED', 'COMMITTED', 'ABORTED'],
                        true,
                    )
                    || !\hash_equals(
                        (string)$transactionId,
                        (string)($transaction['transaction_id'] ?? ''),
                    )
                ) {
                    return false;
                }
                continue;
            }
            if (!$this->validGenericSecurityTransaction(
                (string)$transactionId,
                $transaction,
            )) {
                return false;
            }
            $phase = (string)$transaction['phase'];
            $controllerPhase = (string)$transaction['controller_phase'];
            $assigned = (int)$transaction['assigned_generation'];
            $controllerGeneration = (int)$transaction['controller_generation'];
            $pendingAudit = (bool)$transaction['generation_audit_pending'];
            $publicationId = (string)$transaction['publication_transaction_id'];
            $attempts = (array)$transaction['publication_attempts'];
            $terminalPublication = \hash_equals(
                'CONTROLLER_COMMITTED',
                $controllerPhase,
            );
            if ((\hash_equals('PREPARED', $phase) && $assigned !== 0)
                || (\in_array(
                        $phase,
                        ['RESERVED', 'LEDGER_COMMITTED', 'BROKER_COMMITTED'],
                        true,
                    ) && $assigned < 1)
                || (\hash_equals('BROKER_COMMITTED', $phase)
                    && !$this->validGenericNativeCommitReceipt($transaction))
                || (!\hash_equals('BROKER_COMMITTED', $phase)
                    && (\array_key_exists('native_commit_receipt', $transaction)
                        || \array_key_exists(
                            'broker_committed_at',
                            $transaction,
                        )))
                || (!\hash_equals('BROKER_COMMITTED', $phase)
                    && ($controllerGeneration !== 0
                        || !\hash_equals('PENDING', $controllerPhase)))
                || ($controllerGeneration === 0
                    && (!\hash_equals('PENDING', $controllerPhase)
                        || $pendingAudit
                        || $publicationId !== ''))
                || ($controllerGeneration > 0
                    && \hash_equals('PENDING', $controllerPhase)
                    && !$pendingAudit)
                || (\in_array(
                        $controllerPhase,
                        ['PUBLICATION_PENDING', 'CONTROLLER_COMMITTED'],
                        true,
                    ) && $pendingAudit)
                || ($pendingAudit && $controllerGeneration < 1)
                || (\in_array(
                        $controllerPhase,
                        ['APPLIED', 'PUBLICATION_PENDING', 'CONTROLLER_COMMITTED'],
                        true,
                    ) && $publicationId === '')
                || ($publicationId === '' && $attempts !== [])
                || (!$terminalPublication
                    && (\array_key_exists(
                            'publication_generation',
                            $transaction,
                        )
                        || \array_key_exists(
                            'publication_config_digest',
                            $transaction,
                        )))
                || ($terminalPublication
                    && (!\is_int(
                            $transaction['publication_generation'] ?? null,
                        )
                        || (int)$transaction['publication_generation']
                            < $controllerGeneration
                        || \preg_match(
                            '/\A[a-f0-9]{64}\z/D',
                            (string)(
                                $transaction['publication_config_digest'] ?? ''
                            ),
                        ) !== 1))
                || \count($attempts) > 16
            ) {
                return false;
            }
            $seenAttempts = [];
            foreach ($attempts as $attempt) {
                if (!\is_string($attempt)
                    || \preg_match('/\A[a-f0-9]{32}\z/D', $attempt) !== 1
                    || isset($seenAttempts[$attempt])
                ) {
                    return false;
                }
                $seenAttempts[$attempt] = true;
            }
            if ($publicationId !== ''
                && (\preg_match('/\A[a-f0-9]{32}\z/D', $publicationId) !== 1
                    || !isset($seenAttempts[$publicationId])
                    || !\in_array(
                        $controllerPhase,
                        [
                            'PENDING',
                            'APPLIED',
                            'PUBLICATION_PENDING',
                            'CONTROLLER_COMMITTED',
                        ],
                        true,
                    ))
            ) {
                return false;
            }
        }
        return true;
    }

    /** @param array<string,mixed> $transaction */
    private function validGenericNativeCommitReceipt(array $transaction): bool
    {
        $receipt = $transaction['native_commit_receipt'] ?? null;
        $assigned = (int)($transaction['assigned_generation'] ?? 0);
        $commitAnchor = (string)(
            $transaction['native_commit_anchor_digest'] ?? ''
        );
        if (!\is_array($receipt)
            || $assigned < 1
            || \preg_match('/\A[a-f0-9]{64}\z/D', $commitAnchor) !== 1
            || !\is_int($receipt['assigned'] ?? null)
            || !\is_int($receipt['allocated'] ?? null)
            || !\is_int($receipt['committed'] ?? null)
            || (int)$receipt['assigned'] !== $assigned
            || (int)$receipt['allocated'] < $assigned
            || (int)$receipt['committed'] < $assigned
            || (int)$receipt['committed'] > (int)$receipt['allocated']
            || \preg_match(
                '/\A[a-f0-9]{64}\z/D',
                (string)($receipt['ledger_digest'] ?? ''),
            ) !== 1
            || \hash_equals(
                \str_repeat('0', 64),
                (string)($receipt['ledger_digest'] ?? ''),
            )
            || \preg_match(
                '/\A[a-f0-9]{64}\z/D',
                (string)($receipt['anchor_digest'] ?? ''),
            ) !== 1
        ) {
            return false;
        }
        return \hash_equals(
            $commitAnchor,
            (string)$receipt['anchor_digest'],
        );
    }

    /**
     * @param array<string,mixed> $enrollmentTransactions
     * @param array<string,mixed> $rotationTransactions
     * @param array<string,mixed> $securityTransactions
     */
    private function validControllerGenerationAllocations(
        array $enrollmentTransactions,
        array $rotationTransactions,
        array $securityTransactions,
    ): bool {
        $owners = [];
        foreach ([
            'enrollment' => $enrollmentTransactions,
            'rotation' => $rotationTransactions,
            'security' => $securityTransactions,
        ] as $kind => $transactions) {
            foreach ($transactions as $transactionId => $transaction) {
                if (!\is_array($transaction)) {
                    return false;
                }
                $generation = (int)(
                    $transaction['controller_generation'] ?? 0
                );
                if ($generation < 1) {
                    continue;
                }
                $owner = $kind . ':' . (string)$transactionId;
                if (isset($owners[$generation])
                    && !\hash_equals($owners[$generation], $owner)
                ) {
                    return false;
                }
                $owners[$generation] = $owner;
            }
        }
        return true;
    }

    /**
     * Native generations are host-global, not transaction-family local. A
     * duplicate number across enrollment, rotation and generic security
     * records would make attestation receipts ambiguous after restart.
     *
     * @param array<string,mixed> $enrollmentTransactions
     * @param array<string,mixed> $rotationTransactions
     * @param array<string,mixed> $securityTransactions
     */
    private function validSecurityGenerationAllocations(
        array $enrollmentTransactions,
        array $rotationTransactions,
        array $securityTransactions,
        int $allocatedHighWater,
        int $committedHighWater,
    ): bool {
        $owners = [];
        $pendingAllocationOwners = [];
        foreach ([
            'enrollment' => [$enrollmentTransactions, 'security_generation'],
            'rotation' => [$rotationTransactions, 'security_generation'],
            'security' => [$securityTransactions, 'assigned_generation'],
        ] as $kind => [$transactions, $generationField]) {
            foreach ((array)$transactions as $transactionId => $transaction) {
                if (!\is_array($transaction)) {
                    return false;
                }
                $generation = (int)($transaction[$generationField] ?? 0);
                if ($generation < 0 || $generation > $allocatedHighWater) {
                    return false;
                }
                $owner = $kind . ':' . (string)$transactionId;
                $phase = (string)($transaction['phase'] ?? '');
                $pendingAllocation = match ($kind) {
                    'enrollment' => \in_array($phase, [
                        'PREPARED',
                        'ABORT_PENDING',
                        'LEDGER_COMMITTED',
                    ], true),
                    'rotation' => \in_array($phase, [
                        'PREPARED',
                        'NATIVE_PREPARED',
                        'LEDGER_COMMITTED',
                    ], true),
                    'security' => (int)($transaction['schema_version'] ?? 1) >= 2
                        && \in_array($phase, [
                            'PREPARED',
                            'RESERVED',
                            'LEDGER_COMMITTED',
                        ], true),
                    default => false,
                };
                if ($pendingAllocation) {
                    $pendingAllocationOwners[$owner] = true;
                    if ($generation > 0 && $generation <= $committedHighWater) {
                        return false;
                    }
                }
                if ($generation === 0) {
                    continue;
                }
                if (isset($owners[$generation])
                    && !\hash_equals($owners[$generation], $owner)
                ) {
                    return false;
                }
                $owners[$generation] = $owner;
                $nativeCommitted = match ($kind) {
                    'enrollment' => \in_array(
                        $phase,
                        ['BROKER_COMMITTED', 'COMMITTED', 'SUPERSEDED'],
                        true,
                    ),
                    'rotation' => \in_array($phase, [
                        'BROKER_COMMITTED',
                        'CONTROLLER_COMMITTED',
                        'FINALIZED',
                    ], true),
                    // Legacy generic COMMITTED was ambiguous; schema-2 uses
                    // BROKER_COMMITTED only after a verified Native receipt.
                    'security' => (int)($transaction['schema_version'] ?? 1) >= 2
                        && \hash_equals('BROKER_COMMITTED', $phase),
                    default => false,
                };
                if ($nativeCommitted && $generation > $committedHighWater) {
                    return false;
                }
            }
        }
        return $committedHighWater <= $allocatedHighWater
            && \count($pendingAllocationOwners) <= 1;
    }

    /**
     * Validate every security-generation-bearing after-image against the one
     * host-global transaction that allocated its generation.
     *
     * @param array<string,mixed> $enrollments
     * @param array<string,mixed> $tombstones
     * @param array<string,mixed> $domainOwnership
     * @param array<string,mixed> $enrollmentTransactions
     * @param array<string,mixed> $rotationTransactions
     * @param array<string,mixed> $securityTransactions
     */
    private function validSecurityAuthorityGenerationClosure(
        array $enrollments,
        array $tombstones,
        array $domainOwnership,
        array $enrollmentTransactions,
        array $rotationTransactions,
        array $securityTransactions,
        int $allocatedHighWater,
    ): bool {
        $owners = [];
        foreach ($enrollmentTransactions as $transactionId => $transaction) {
            if (\is_array($transaction)
                && (int)($transaction['security_generation'] ?? 0) > 0
            ) {
                $owners[(int)$transaction['security_generation']] = [
                    'family' => 'enrollment',
                    'id' => (string)$transactionId,
                    'transaction' => $transaction,
                ];
            }
        }
        foreach ($rotationTransactions as $transactionId => $transaction) {
            if (\is_array($transaction)
                && (int)($transaction['security_generation'] ?? 0) > 0
            ) {
                $owners[(int)$transaction['security_generation']] = [
                    'family' => 'rotation',
                    'id' => (string)$transactionId,
                    'transaction' => $transaction,
                ];
            }
        }
        foreach ($securityTransactions as $transactionId => $transaction) {
            if (\is_array($transaction)
                && (int)($transaction['assigned_generation'] ?? 0) > 0
            ) {
                $owners[(int)$transaction['assigned_generation']] = [
                    'family' => 'security',
                    'id' => (string)$transactionId,
                    'transaction' => $transaction,
                ];
            }
        }
        try {
            foreach ($enrollments as $projectUuid => $enrollment) {
                if (!\is_array($enrollment)
                    || !$this->validProjectUuid((string)$projectUuid)
                    || !\hash_equals(
                        (string)$projectUuid,
                        (string)($enrollment['project_uuid'] ?? ''),
                    )
                    || !\is_int($enrollment['security_generation'] ?? null)
                ) {
                    return false;
                }
                $generation = (int)$enrollment['security_generation'];
                $owner = $owners[$generation] ?? null;
                if ($generation < 1
                    || $generation > $allocatedHighWater
                    || !\is_array($owner)
                ) {
                    return false;
                }
                $transaction = (array)$owner['transaction'];
                $family = (string)$owner['family'];
                if (($family === 'enrollment'
                        && (!\hash_equals(
                                (string)$projectUuid,
                                (string)($transaction['project_uuid'] ?? ''),
                            )
                            || !\hash_equals(
                                (string)($owner['id'] ?? ''),
                                (string)(
                                    $enrollment['enrollment_transaction_id']
                                        ?? ''
                                ),
                            )
                            || !\hash_equals(
                                (string)($owner['id'] ?? ''),
                                (string)(
                                    $enrollment[
                                        'native_authorization_transaction_id'
                                    ] ?? ''
                                ),
                            )
                            || !\in_array(
                                (string)($transaction['phase'] ?? ''),
                                [
                                    'LEDGER_COMMITTED',
                                    'BROKER_COMMITTED',
                                    'COMMITTED',
                                ],
                                true,
                            )
                            || !$this->validEnrollmentSecuritySnapshot(
                                $enrollment,
                                (string)$projectUuid,
                            )))
                    || ($family === 'rotation'
                        && (!\hash_equals(
                                (string)$projectUuid,
                                (string)($transaction['new_project_uuid'] ?? ''),
                            )
                            || !\in_array(
                                (string)($transaction['phase'] ?? ''),
                                [
                                    'BROKER_COMMITTED',
                                    'CONTROLLER_COMMITTED',
                                    'FINALIZED',
                                ],
                                true,
                            )
                            || !\in_array(
                                (string)(
                                    $transaction['controller_phase'] ?? ''
                                ),
                                [
                                    'APPLIED',
                                    'PUBLICATION_PENDING',
                                    'CONTROLLER_COMMITTED',
                                ],
                                true,
                            )
                            || (\hash_equals(
                                    'FINALIZED',
                                    (string)($transaction['phase'] ?? ''),
                                )
                                ? !$this->projectIdentityRotationProjectionMatchesEnrollment(
                                    $transaction,
                                    (array)(
                                        $transaction[
                                            'final_enrollment_snapshot'
                                        ] ?? []
                                    ),
                                    $enrollment,
                                )
                                : !$this->validProjectIdentityRotationNewEnrollment(
                                    $transaction,
                                    $enrollments,
                                ))))
                    || !\in_array($family, ['enrollment', 'rotation'], true)
                ) {
                    return false;
                }
            }
            foreach ($tombstones as $key => $tombstone) {
                if (!\is_array($tombstone)
                    || !\is_int($tombstone['generation'] ?? null)
                ) {
                    return false;
                }
                $generation = (int)$tombstone['generation'];
                $owner = $owners[$generation] ?? null;
                if ($generation < 1
                    || $generation > $allocatedHighWater
                    || !\is_array($owner)
                    || !$this->validSecurityTombstoneOwner(
                        (string)$key,
                        $tombstone,
                        $owner,
                    )
                ) {
                    return false;
                }
            }
            foreach ($domainOwnership as $domain => $ownership) {
                if (!\is_array($ownership)
                    || !\hash_equals(
                        (string)$domain,
                        $this->normalizeDomain((string)$domain),
                    )
                    || !\hash_equals(
                        (string)$domain,
                        (string)($ownership['domain'] ?? ''),
                    )
                    || !$this->validProjectUuid(
                        (string)($ownership['project_uuid'] ?? ''),
                    )
                    || !\hash_equals(
                        $this->canonicalRouteId(
                            (string)$ownership['project_uuid'],
                            (string)$domain,
                        ),
                        (string)($ownership['route_id'] ?? ''),
                    )
                    || !\is_int(
                        $ownership['enrollment_security_generation'] ?? null,
                    )
                    || !\is_int(
                        $ownership['domain_security_generation'] ?? null,
                    )
                    || !\is_int($ownership['ownership_generation'] ?? null)
                ) {
                    return false;
                }
                $enrollmentGeneration = (int)(
                    $ownership['enrollment_security_generation']
                );
                $domainGeneration = (int)(
                    $ownership['domain_security_generation']
                );
                $ownershipGeneration = (int)$ownership['ownership_generation'];
                if ($enrollmentGeneration < 1
                    || $domainGeneration < 0
                    || $ownershipGeneration !== \max(
                        $enrollmentGeneration,
                        $domainGeneration,
                    )
                    || $ownershipGeneration > $allocatedHighWater
                    || !$this->validDomainOwnershipEnrollmentGeneration(
                        $ownership,
                        $owners[$enrollmentGeneration] ?? null,
                    )
                    || ($domainGeneration > 0
                        && !$this->validDomainOwnershipDomainGeneration(
                            $ownership,
                            $owners[$domainGeneration] ?? null,
                        ))
                ) {
                    return false;
                }
            }
        } catch (\Throwable) {
            return false;
        }
        return true;
    }

    /**
     * @param array<string,mixed> $ownership
     * @param array{family:mixed,id:mixed,transaction:mixed}|null $owner
     */
    private function validDomainOwnershipEnrollmentGeneration(
        array $ownership,
        ?array $owner,
    ): bool {
        if (!\is_array($owner)
            || !\is_array($owner['transaction'] ?? null)
        ) {
            return false;
        }
        $projectUuid = (string)($ownership['project_uuid'] ?? '');
        $generation = (int)(
            $ownership['enrollment_security_generation'] ?? 0
        );
        $family = (string)($owner['family'] ?? '');
        $transaction = (array)$owner['transaction'];
        if (\hash_equals('enrollment', $family)) {
            return (int)($transaction['security_generation'] ?? 0)
                    === $generation
                && \hash_equals(
                    $projectUuid,
                    (string)($transaction['project_uuid'] ?? ''),
                )
                && \in_array(
                    (string)($transaction['phase'] ?? ''),
                    [
                        'LEDGER_COMMITTED',
                        'BROKER_COMMITTED',
                        'COMMITTED',
                        'SUPERSEDED',
                    ],
                    true,
                );
        }
        if (!\hash_equals('rotation', $family)) {
            return false;
        }
        return (int)($transaction['security_generation'] ?? 0) === $generation
            && \hash_equals(
                $projectUuid,
                (string)($transaction['new_project_uuid'] ?? ''),
            )
            && \in_array(
                (string)($transaction['phase'] ?? ''),
                ['BROKER_COMMITTED', 'CONTROLLER_COMMITTED', 'FINALIZED'],
                true,
            )
            && \in_array(
                (string)($transaction['controller_phase'] ?? ''),
                ['APPLIED', 'PUBLICATION_PENDING', 'CONTROLLER_COMMITTED'],
                true,
            );
    }

    /**
     * @param array<string,mixed> $ownership
     * @param array{family:mixed,id:mixed,transaction:mixed}|null $owner
     */
    private function validDomainOwnershipDomainGeneration(
        array $ownership,
        ?array $owner,
    ): bool {
        if (!\is_array($owner)
            || !\is_array($owner['transaction'] ?? null)
        ) {
            return false;
        }
        $domain = (string)($ownership['domain'] ?? '');
        $projectUuid = (string)($ownership['project_uuid'] ?? '');
        $generation = (int)(
            $ownership['domain_security_generation'] ?? 0
        );
        $family = (string)($owner['family'] ?? '');
        $transaction = (array)$owner['transaction'];
        if (\hash_equals('security', $family)) {
            $facts = $transaction['controller_facts'] ?? null;
            $transfer = \is_array($facts)
                ? ($facts['transfer'] ?? null)
                : null;
            $candidate = \is_array($facts)
                ? ($facts['candidate'] ?? null)
                : null;
            return \hash_equals(
                    'DOMAIN_TRANSFER',
                    (string)($transaction['kind'] ?? ''),
                )
                && (int)($transaction['assigned_generation'] ?? 0)
                    === $generation
                && \in_array(
                    (string)($transaction['phase'] ?? ''),
                    ['LEDGER_COMMITTED', 'BROKER_COMMITTED'],
                    true,
                )
                && \is_array($transfer)
                && \is_array($candidate)
                && \hash_equals(
                    $domain,
                    (string)($transfer['domain'] ?? ''),
                )
                && \hash_equals(
                    $projectUuid,
                    (string)($transfer['to_project_uuid'] ?? ''),
                )
                && \hash_equals(
                    (string)($ownership['route_id'] ?? ''),
                    (string)($candidate['route_id'] ?? ''),
                );
        }
        if (!\hash_equals('rotation', $family)
            || (int)($transaction['security_generation'] ?? 0) !== $generation
            || !\hash_equals(
                $projectUuid,
                (string)($transaction['new_project_uuid'] ?? ''),
            )
            || !\in_array(
                (string)($transaction['phase'] ?? ''),
                ['BROKER_COMMITTED', 'CONTROLLER_COMMITTED', 'FINALIZED'],
                true,
            )
            || !\in_array(
                (string)($transaction['controller_phase'] ?? ''),
                ['APPLIED', 'PUBLICATION_PENDING', 'CONTROLLER_COMMITTED'],
                true,
            )
        ) {
            return false;
        }
        foreach ((array)($transaction['route_migration_facts'] ?? []) as $route) {
            if (\is_array($route)
                && \hash_equals($domain, (string)($route['domain'] ?? ''))
                && \hash_equals(
                    (string)($ownership['route_id'] ?? ''),
                    $this->canonicalRouteId($projectUuid, $domain),
                )
            ) {
                return true;
            }
        }
        return false;
    }

    /**
     * @param array<string,mixed> $tombstone
     * @param array{family:mixed,id:mixed,transaction:mixed} $owner
     */
    private function validSecurityTombstoneOwner(
        string $key,
        array $tombstone,
        array $owner,
    ): bool {
        $kind = (string)($tombstone['kind'] ?? '');
        $family = (string)($owner['family'] ?? '');
        $transaction = \is_array($owner['transaction'] ?? null)
            ? $owner['transaction']
            : [];
        if (\hash_equals('project_identity_rotation', $kind)) {
            $rotationId = (string)($tombstone['rotation_id'] ?? '');
            if ($family !== 'rotation'
                || !\hash_equals((string)($owner['id'] ?? ''), $rotationId)
                || (int)($transaction['security_generation'] ?? 0)
                    !== (int)($tombstone['generation'] ?? 0)
                || !\in_array(
                    (string)($transaction['phase'] ?? ''),
                    [
                        'BROKER_COMMITTED',
                        'CONTROLLER_COMMITTED',
                        'FINALIZED',
                    ],
                    true,
                )
                || !\in_array(
                    (string)($transaction['controller_phase'] ?? ''),
                    ['APPLIED', 'PUBLICATION_PENDING', 'CONTROLLER_COMMITTED'],
                    true,
                )
            ) {
                return false;
            }
            if (\str_starts_with($key, 'project:')) {
                return \hash_equals(
                        $key,
                        'project:' . (string)$transaction['old_project_uuid'],
                    )
                    && \hash_equals(
                        (string)($tombstone['project_uuid'] ?? ''),
                        (string)$transaction['old_project_uuid'],
                    )
                    && \hash_equals(
                        (string)($tombstone['to_project_uuid'] ?? ''),
                        (string)$transaction['new_project_uuid'],
                    )
                    && \hash_equals(
                        (string)($tombstone['credential_id'] ?? ''),
                        (string)($transaction['old_credential_id'] ?? ''),
                    );
            }
            if (!\str_starts_with($key, 'domain:')) {
                return false;
            }
            $domain = (string)($tombstone['domain'] ?? '');
            $routeMatched = false;
            foreach ((array)(
                $transaction['route_migration_facts'] ?? []
            ) as $route) {
                if (\is_array($route)
                    && \hash_equals($domain, (string)($route['domain'] ?? ''))
                    && \hash_equals(
                        (string)($route['route_id'] ?? ''),
                        $this->canonicalRouteId(
                            (string)$transaction['old_project_uuid'],
                            $domain,
                        ),
                    )
                ) {
                    $routeMatched = true;
                    break;
                }
            }
            return $routeMatched
                && \hash_equals($key, 'domain:' . $domain)
                && \hash_equals(
                    (string)($tombstone['from_project_uuid'] ?? ''),
                    (string)$transaction['old_project_uuid'],
                )
                && \hash_equals(
                    (string)($tombstone['to_project_uuid'] ?? ''),
                    (string)$transaction['new_project_uuid'],
                );
        }
        $schema = (int)($transaction['schema_version'] ?? 1);
        if ($family !== 'security'
            || ($schema >= 2
                ? !\in_array(
                    (string)($transaction['phase'] ?? ''),
                    ['LEDGER_COMMITTED', 'BROKER_COMMITTED'],
                    true,
                )
                : !\hash_equals(
                    'COMMITTED',
                    (string)($transaction['phase'] ?? ''),
                ))
            || (int)($transaction['assigned_generation'] ?? 0)
                !== (int)($tombstone['generation'] ?? 0)
        ) {
            return false;
        }
        $facts = \is_array($transaction['controller_facts'] ?? null)
            ? $transaction['controller_facts']
            : [];
        if (\hash_equals('project_revoke', $kind)) {
            $projectUuid = (string)($tombstone['project_uuid'] ?? '');
            $enrollment = \is_array($facts['enrollment'] ?? null)
                ? $facts['enrollment']
                : [];
            return \hash_equals(
                    'PROJECT_REVOKE',
                    (string)($transaction['kind'] ?? ''),
                )
                && \hash_equals($key, 'project:' . $projectUuid)
                && ($schema < 2
                    ? $facts === []
                    : ($this->validEnrollmentSecuritySnapshot(
                            $enrollment,
                            $projectUuid,
                        )
                        && \hash_equals(
                            $projectUuid,
                            (string)($facts['project_uuid'] ?? ''),
                        )
                        && \hash_equals(
                            (string)($tombstone['credential_id'] ?? ''),
                            (string)($enrollment['credential_id'] ?? ''),
                        )));
        }
        if (!\hash_equals('domain_transfer', $kind)) {
            return false;
        }
        $domain = (string)($tombstone['domain'] ?? '');
        $transfer = \is_array($facts['transfer'] ?? null)
            ? $facts['transfer']
            : [];
        $candidate = \is_array($facts['candidate'] ?? null)
            ? $facts['candidate']
            : [];
        return \hash_equals(
                'DOMAIN_TRANSFER',
                (string)($transaction['kind'] ?? ''),
            )
            && \hash_equals($key, 'domain:' . $domain)
            && ($schema < 2
                ? $transfer === []
                : (\hash_equals(
                    $domain,
                    (string)($transfer['domain'] ?? ''),
                )
                && \hash_equals(
                    (string)($tombstone['from_project_uuid'] ?? ''),
                    (string)($transfer['from_project_uuid'] ?? ''),
                )
                && \hash_equals(
                    (string)($tombstone['to_project_uuid'] ?? ''),
                    (string)($transfer['to_project_uuid'] ?? ''),
                )
                && \hash_equals(
                    (string)($tombstone['transfer_id'] ?? ''),
                    (string)($facts['transfer_id'] ?? ''),
                )
                && \hash_equals(
                    (string)($tombstone['source_route_id'] ?? ''),
                    (string)($transfer['source_route_id'] ?? ''),
                )
                && \hash_equals(
                    (string)($candidate['route_id'] ?? ''),
                    $this->canonicalRouteId(
                        (string)($transfer['to_project_uuid'] ?? ''),
                        $domain,
                    ),
                )));
    }

    /**
     * @param array<string,mixed> $transactions
     */
    private function controllerGenerationHighWater(
        array $enrollmentTransactions,
        array $rotationTransactions,
        array $securityTransactions,
    ): int {
        $highWater = 0;
        foreach ([
            $enrollmentTransactions,
            $rotationTransactions,
            $securityTransactions,
        ] as $transactions) {
            foreach ($transactions as $transaction) {
                if (\is_array($transaction)) {
                    $highWater = \max(
                        $highWater,
                        (int)($transaction['controller_generation'] ?? 0),
                    );
                }
            }
        }
        return $highWater;
    }

    private function nextSecurityGeneration(): int
    {
        $transactionHighWater = 0;
        foreach ((array)($this->state['enrollment_transactions'] ?? []) as $transaction) {
            if (\is_array($transaction)) {
                $transactionHighWater = \max(
                    $transactionHighWater,
                    (int)($transaction['security_generation'] ?? 0),
                );
            }
        }
        $generation = \max(
            (int)($this->state['security_generation_high_water'] ?? 0),
            $this->securityGenerationHighWater(
                (array)($this->state['enrollments'] ?? []),
                (array)($this->state['security']['tombstones'] ?? []),
            ),
            $transactionHighWater,
        ) + 1;
        $this->state['security_generation_high_water'] = $generation;
        return $generation;
    }

    /**
     * @return array{status:string,payload?:array<string,mixed>}
     */
    private function loadSecurityLedger(bool $allowRepair = true): array
    {
        $file = $this->securityLedgerFile();
        $untrustedMarker = $file . '.untrusted';
        if (\is_file($untrustedMarker) || \is_link($untrustedMarker)) {
            return ['status' => 'invalid'];
        }
        if (!\file_exists($file) && !\is_link($file)) {
            return ['status' => 'missing'];
        }
        if (!\is_file($file) || \is_link($file)) {
            if ($allowRepair) {
                $this->atomicWrite($untrustedMarker, \gmdate(DATE_ATOM) . "\n", 0600);
            }
            return ['status' => 'invalid'];
        }
        try {
            $raw = $this->readStableRegularFile(
                $file,
                64 * 1024 * 1024,
                'Gateway security ledger',
            );
        } catch (\Throwable) {
            if ($allowRepair) {
                try {
                    $this->atomicWrite(
                        $untrustedMarker,
                        \gmdate(DATE_ATOM) . "\n",
                        0600,
                    );
                } catch (\Throwable) {
                }
            }
            return ['status' => 'invalid'];
        }
        $envelope = \json_decode($raw, true);
        $payload = \is_array($envelope) && \is_array($envelope['payload'] ?? null)
            ? $envelope['payload']
            : null;
        $hash = \is_array($envelope) ? (string)($envelope['sha256'] ?? '') : '';
        if (!\is_array($payload)
            || !\in_array((int)($payload['schema_version'] ?? 0), [5, 6, 7, 8], true)
            || !\is_array($payload['enrollments'] ?? null)
            || !\is_array($payload['tombstones'] ?? null)
            || !\is_array($payload['enrollment_transactions'] ?? null)
            || !\is_array($payload['rotation_transactions'] ?? null)
            || !\is_array($payload['security_transactions'] ?? null)
            || !\is_array($payload['domain_ownership'] ?? null)
            || !\is_array($payload['certificate_floors'] ?? null)
            || ((int)($payload['schema_version'] ?? 0) >= 6
                && !\is_array($payload['instance_retirements'] ?? null))
            || ((int)($payload['schema_version'] ?? 0) >= 7
                && !\is_bool($payload['nonce_wal_established'] ?? null))
            || ((int)($payload['schema_version'] ?? 0) >= 8
                && !\is_array(
                    $payload['security_publication_recovery_authority'] ?? null
                ))
            || !\array_key_exists('allocated_high_water', $payload)
            || !\array_key_exists('committed_high_water', $payload)
            || !\is_int($payload['allocated_high_water'])
            || !\is_int($payload['committed_high_water'])
            || (int)$payload['allocated_high_water'] < 0
            || (int)$payload['committed_high_water'] < 0
            || (int)$payload['committed_high_water']
                > (int)$payload['allocated_high_water']
            || !\is_string($payload['native_security_ledger_digest'] ?? null)
            || !\is_string($payload['native_security_anchor_digest'] ?? null)
            || !\is_bool($payload['native_security_attested'] ?? null)
            || \preg_match(
                '/\A[a-f0-9]{64}\z/D',
                (string)($payload['native_security_ledger_digest'] ?? ''),
            ) !== 1
            || \preg_match(
                '/\A[a-f0-9]{64}\z/D',
                (string)($payload['native_security_anchor_digest'] ?? ''),
            ) !== 1
            || (((int)($payload['allocated_high_water'] ?? 0) > 0
                    || (array)($payload['enrollments'] ?? []) !== []
                    || (array)($payload['tombstones'] ?? []) !== []
                    || (array)($payload['enrollment_transactions'] ?? []) !== []
                    || (array)($payload['rotation_transactions'] ?? []) !== []
                    || (array)($payload['security_transactions'] ?? []) !== []
                    || (array)(
                        $payload['security_publication_recovery_authority'] ?? []
                    ) !== []
                    || (array)($payload['domain_ownership'] ?? []) !== []
                    || (array)($payload['certificate_floors'] ?? []) !== []
                    || (array)($payload['instance_retirements'] ?? []) !== [])
                && \hash_equals(
                    \str_repeat('0', 64),
                    (string)($payload['native_security_ledger_digest'] ?? ''),
                ))
            || (($payload['native_security_attested'] ?? null) === false
                && ((int)($payload['allocated_high_water'] ?? 0) !== 0
                    || (int)($payload['committed_high_water'] ?? 0) !== 0
                    || (array)($payload['enrollments'] ?? []) !== []
                    || (array)($payload['tombstones'] ?? []) !== []
                    || (array)($payload['enrollment_transactions'] ?? []) !== []
                    || (array)($payload['rotation_transactions'] ?? []) !== []
                    || (array)($payload['security_transactions'] ?? []) !== []
                    || (array)(
                        $payload['security_publication_recovery_authority'] ?? []
                    ) !== []
                    || (array)($payload['domain_ownership'] ?? []) !== []
                    || (array)($payload['certificate_floors'] ?? []) !== []
                    || (array)($payload['instance_retirements'] ?? []) !== []
                    || !\hash_equals(
                        \str_repeat('0', 64),
                        (string)($payload['native_security_ledger_digest'] ?? ''),
                    )
                    || !\hash_equals(
                        \str_repeat('0', 64),
                        (string)($payload['native_security_anchor_digest'] ?? ''),
                    )))
            || (($payload['native_security_attested'] ?? null) === true
                && \hash_equals(
                    \str_repeat('0', 64),
                    (string)($payload['native_security_ledger_digest'] ?? ''),
                ))
            || !\preg_match('/\A[a-f0-9]{64}\z/D', $hash)
            || !\hash_equals($hash, \hash('sha256', $this->canonicalJson($payload)))
            || !$this->validSecurityPublicationRecoveryAuthority(
                (array)(
                    $payload['security_publication_recovery_authority'] ?? []
                ),
                (array)($payload['security_transactions'] ?? []),
                (array)($payload['rotation_transactions'] ?? []),
                false,
            )
            || !$this->validEnrollmentLedgerClosure(
                (array)($payload['enrollment_transactions'] ?? []),
                (array)($payload['enrollments'] ?? []),
                (array)($payload['tombstones'] ?? []),
                (array)($payload['rotation_transactions'] ?? []),
                (array)($payload['security_transactions'] ?? []),
            )
            || !$this->validGenericSecurityTransactions(
                (array)($payload['security_transactions'] ?? []),
            )
            || !$this->validProjectIdentityRotationTransactions(
                (array)($payload['rotation_transactions'] ?? []),
                (array)($payload['enrollments'] ?? []),
                (array)($payload['tombstones'] ?? []),
                (array)($payload['security_transactions'] ?? []),
                (array)($payload['enrollment_transactions'] ?? []),
            )
            || !$this->validControllerGenerationAllocations(
                (array)($payload['enrollment_transactions'] ?? []),
                (array)($payload['rotation_transactions'] ?? []),
                (array)($payload['security_transactions'] ?? []),
            )
            || !$this->validSecurityGenerationAllocations(
                (array)($payload['enrollment_transactions'] ?? []),
                (array)($payload['rotation_transactions'] ?? []),
                (array)($payload['security_transactions'] ?? []),
                (int)($payload['allocated_high_water'] ?? 0),
                (int)($payload['committed_high_water'] ?? 0),
            )
            || !$this->validSecurityAuthorityGenerationClosure(
                (array)($payload['enrollments'] ?? []),
                (array)($payload['tombstones'] ?? []),
                (array)($payload['domain_ownership'] ?? []),
                (array)($payload['enrollment_transactions'] ?? []),
                (array)($payload['rotation_transactions'] ?? []),
                (array)($payload['security_transactions'] ?? []),
                (int)($payload['allocated_high_water'] ?? 0),
