    private function freshInstallBootstrapAllowed(): bool
    {
        $marker = $this->initializationMarkerFile();
        if (\file_exists($marker) || \is_link($marker)) {
            try {
                $decoded = \json_decode($this->readStableRegularFile(
                    $marker,
                    16_384,
                    'Gateway initialization marker',
                ), true);
                $payload = \is_array($decoded['payload'] ?? null)
                    ? $decoded['payload']
                    : null;
                $schemaVersion = (int)($payload['schema_version'] ?? 0);
                $envelopeTrusted = \is_array($payload)
                    && \hash_equals(self::PROTOCOL, (string)($payload['protocol'] ?? ''))
                    && \hash_equals($this->hostId(), (string)($payload['host_id'] ?? ''))
                    && \hash_equals(
                        (string)($decoded['sha256'] ?? ''),
                        \hash('sha256', $this->canonicalJson($payload)),
                    );
                if ($schemaVersion === 2) {
                    $ledgerDigest = $this->fileHash($this->securityLedgerFile());
                    $anchorDigest = $this->fileHash($this->securityAnchorFile());
                    $this->initializationMarkerTrusted = $envelopeTrusted
                        && $ledgerDigest !== ''
                        && $anchorDigest !== ''
                        && \hash_equals(
                            $ledgerDigest,
                            (string)($payload['security_ledger_sha256'] ?? ''),
                        )
                        && \hash_equals(
                            $anchorDigest,
                            (string)($payload['security_anchor_sha256'] ?? ''),
                        );
                } elseif ($schemaVersion === 3) {
                    $this->initializationMarkerTrusted = $envelopeTrusted
                        && \preg_match(
                            '/\A[a-f0-9]{32}\z/D',
                            (string)($payload['initialization_id'] ?? ''),
                        ) === 1
                        && \is_string($payload['initialized_at'] ?? null)
                        && (string)$payload['initialized_at'] !== '';
                } else {
                    $this->initializationMarkerTrusted = false;
                }
                if ($this->initializationMarkerTrusted) {
                    $this->initializationMarkerSchemaVersion = $schemaVersion;
                    $this->initializationMarkerPayload = $payload;
                }
            } catch (\Throwable) {
                $this->initializationMarkerTrusted = false;
                $this->initializationMarkerSchemaVersion = 0;
                $this->initializationMarkerPayload = [];
            }
            return false;
        }
        $this->initializationMarkerTrusted = true;
        $this->initializationMarkerSchemaVersion = 0;
        $this->initializationMarkerPayload = [];
        return !$this->gatewayHasHistoricalMutableState();
    }

    private function gatewayHasHistoricalMutableState(): bool
    {
        foreach ([
            $this->stateFile(),
            $this->leaseCheckpointFile(),
            $this->securityLedgerFile(),
            $this->securityLedgerPendingFile(),
            $this->securityLedgerFile() . '.untrusted',
            $this->publicationFile(),
            $this->routeLkgFile(),
            $this->journalFile(),
            $this->journalFile() . '.1',
            $this->nonceWalFile(),
            $this->endpointFile(),
            $this->diskPressureMarkerFile(),
            $this->stateDir() . DIRECTORY_SEPARATOR . 'neutral-cert.pem',
            $this->stateDir() . DIRECTORY_SEPARATOR . 'neutral-key.pem',
            $this->stateDir() . DIRECTORY_SEPARATOR
                . 'emergency-revocations-v1.tsv',
            $this->configFile(),
            $this->securityAnchorFile(),
            $this->trustDir() . DIRECTORY_SEPARATOR . 'security-anchor.json',
            $this->trustDir() . DIRECTORY_SEPARATOR . 'wls-edge-2.initialized.json',
            $this->journalDistrustMarkerFile(),
            $this->trustDir() . DIRECTORY_SEPARATOR . 'snapshot-receipt.key',
            $this->trustDir() . DIRECTORY_SEPARATOR . 'broker-enrollments.tsv',
            $this->trustDir() . DIRECTORY_SEPARATOR . 'broker-security-v2.tsv',
            $this->trustDir() . DIRECTORY_SEPARATOR
                . 'emergency-credentials-v1.tsv',
        ] as $file) {
            if (\file_exists($file) || \is_link($file)) {
                return true;
            }
        }
        foreach ([
            $this->configDir(),
            $this->lkgDir(),
            $this->legacySnapshotRoot(),
            $this->snapshotCandidateRoot(),
            $this->trustDir() . DIRECTORY_SEPARATOR . 'snapshot-receipts',
        ] as $dir) {
            $status = @\lstat($dir);
            if (!\is_array($status)) {
                continue;
            }
            if (\is_link($dir)
                || ((((int)($status['mode'] ?? 0)) & 0170000) !== 0040000)
                || $this->directoryHasEntries($dir)
            ) {
                return true;
            }
        }
        $sealedSnapshotRoot = $this->sealedSnapshotRoot();
        $sealedSnapshotStatus = @\lstat($sealedSnapshotRoot);
        if (\is_array($sealedSnapshotStatus)
            && (\is_link($sealedSnapshotRoot)
                || ((((int)($sealedSnapshotStatus['mode'] ?? 0)) & 0170000) !== 0040000)
            )
        ) {
            return true;
        }
        try {
            foreach ($this->boundedDirectoryEntries(
                $this->trustDir(),
                self::MAX_HOST_DIRECTORY_ENTRIES,
                'Gateway trust directory',
            ) as $entry) {
                if (\str_starts_with(
                    \strtolower($entry),
                    '.snapshot-receipt.key.candidate.',
                )) {
                    return true;
                }
            }
        } catch (\Throwable) {
            return true;
        }
        return false;
    }

    private function persistInitializationMarker(): void
    {
        $file = $this->initializationMarkerFile();
        if (\file_exists($file) || \is_link($file)) {
            if (!$this->initializationMarkerTrusted) {
                throw new \RuntimeException(
                    'Gateway initialization marker is untrusted and cannot be overwritten.'
                );
            }
            if ($this->initializationMarkerSchemaVersion === 3) {
                return;
            }
        }
        $ledgerDigest = $this->fileHash($this->securityLedgerFile());
        $anchorDigest = $this->fileHash($this->securityAnchorFile());
        if ($ledgerDigest === '' || $anchorDigest === '') {
            throw new \RuntimeException(
                'Gateway initialization marker requires committed security anchors.'
            );
        }
        $payload = [
            'schema_version' => 3,
            'protocol' => self::PROTOCOL,
            'host_id' => $this->hostId(),
            'initialization_id' => \bin2hex(\random_bytes(16)),
            'initialized_at' => (string)(
                $this->initializationMarkerPayload['initialized_at']
                    ?? \gmdate(DATE_ATOM)
            ),
        ];
        $encoded = (string)\json_encode([
            'payload' => $payload,
            'sha256' => \hash('sha256', $this->canonicalJson($payload)),
        ], JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR);
        $this->atomicWrite($file, $encoded, 0600);
        $this->initializationMarkerSchemaVersion = 3;
        $this->initializationMarkerPayload = $payload;
        $this->initializationMarkerTrusted = true;
    }

    private function ensureImmutableInitializationMarkerBeforeSecurityMutation(): void
    {
        $file = $this->initializationMarkerFile();
        if (!\file_exists($file) && !\is_link($file)) {
            return;
        }
        if (!$this->initializationMarkerTrusted) {
            throw new \RuntimeException(
                'Gateway initialization marker is untrusted during security mutation.'
            );
        }
        if ($this->initializationMarkerSchemaVersion < 3) {
            $this->persistInitializationMarker();
        }
    }

