    }

    private function diskPressureMarkerActive(): bool
    {
        return \file_exists($this->diskPressureMarkerFile())
            || \is_link($this->diskPressureMarkerFile());
    }

    /** @return array{trusted:bool,stage:string,reason:string} */
    private function diskPressureMarkerEvidence(): array
    {
        try {
            $observed = $this->readStableRegularFileWithStatus(
                $this->diskPressureMarkerFile(),
                2048,
                'Gateway disk-pressure marker',
            );
            $record = $observed['contents'];
            if (\PHP_OS_FAMILY !== 'Windows'
                && ((((int)($observed['status']['mode'] ?? 0)) & 0777) !== 0600)
            ) {
                throw new \RuntimeException(
                    'Gateway disk-pressure marker permissions are unsafe.'
                );
            }
        } catch (\Throwable) {
            return [
                'trusted' => false,
                'stage' => 'DISK_PRESSURE_MARKER_UNTRUSTED',
                'reason' => 'disk_pressure_marker_invalid',
            ];
        }
        if (\preg_match(
            '/\A([^\t\r\n\x00-\x1f\x7f]{1,64})\t'
                . '([A-Z0-9_]{1,64})\t'
                . '([^\t\r\n\x00-\x1f\x7f]{1,1024})\n\z/uD',
            $record,
            $matches,
        ) !== 1) {
            return [
                'trusted' => false,
                'stage' => 'DISK_PRESSURE_MARKER_UNTRUSTED',
                'reason' => 'disk_pressure_marker_invalid',
            ];
        }
        $observedAt = \DateTimeImmutable::createFromFormat(DATE_ATOM, $matches[1]);
        $dateErrors = \DateTimeImmutable::getLastErrors();
        if (!$observedAt instanceof \DateTimeImmutable
            || (\is_array($dateErrors)
                && ((int)($dateErrors['warning_count'] ?? 0) > 0
                    || (int)($dateErrors['error_count'] ?? 0) > 0))
            || !\hash_equals($matches[1], $observedAt->format(DATE_ATOM))
        ) {
            return [
                'trusted' => false,
                'stage' => 'DISK_PRESSURE_MARKER_UNTRUSTED',
                'reason' => 'disk_pressure_marker_invalid',
            ];
        }
        return [
            'trusted' => true,
            'stage' => $matches[2],
            'reason' => $matches[3],
        ];
    }

