        return $file;
    }

    private function healthPort(): int
    {
        return (int)$this->state['health_port'];
    }
}

if (!\defined('WLS_GATEWAY_CONTROLLER_EMBEDDED_TEST')) {
    exit(WlsEdgeGatewayController::main($argv));
}
